insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d5000000-0000-0000-0000-000000000001', 'mrcp2', '96d01c15-e03f-4c99-956d-44b37e38fdbb',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d5000000-0000-0000-0000-000000000001', 'A', 'Increase oxybutynin to 5mg twice daily for better bladder control', false, 'Ruled out because this would worsen her established anticholinergic toxicity (confusion, dry mouth, constipation) and risks precipitating a more severe delirium or falls; the correct response to an adverse reaction is to stop the offending drug, not escalate its dose.', 1),
('d5000000-0000-0000-0000-000000000001', 'B', 'Switch to solifenacin, a more selective antimuscarinic', false, 'Ruled out because although solifenacin has somewhat greater bladder selectivity than oxybutynin, it remains an antimuscarinic and carries a meaningful anticholinergic burden; in a patient who has just developed confusion on one antimuscarinic, swapping to another risks recurrence of the same problem rather than addressing it.', 2),
('d5000000-0000-0000-0000-000000000001', 'C', 'Insert a long-term indwelling urinary catheter', false, 'Ruled out because an indwelling catheter is not indicated for urgency incontinence with preserved voiding; it carries significant risks of catheter-associated urinary tract infection, encrustation and reduced mobility, and should be reserved for retention or where other measures have failed and are not tolerated.', 3),
('d5000000-0000-0000-0000-000000000001', 'D', 'Add trihexyphenidyl to counteract Parkinsonian rigidity while continuing oxybutynin', false, 'Ruled out because trihexyphenidyl is itself a strong anticholinergic agent; adding it would substantially increase her total anticholinergic burden and worsen her confusion, rather than treating the underlying problem.', 4),
('d5000000-0000-0000-0000-000000000001', 'E', 'Stop oxybutynin and start mirabegron', true, $x$Correct. Oxybutynin is a potent antimuscarinic with high anticholinergic burden, and in an older patient with Parkinson's disease it has precipitated confusion, drowsiness and constipation, compounding the risk of further cognitive decline. Mirabegron is a beta-3 adrenoceptor agonist that improves detrusor overactivity without antimuscarinic central nervous system effects, making it the preferred next step; blood pressure should still be monitored as it can cause hypertension.$x$, 5),
('d5000000-0000-0000-0000-000000000002', 'A', 'Start tamsulosin and review renal function in one week', false, 'Ruled out because an alpha-blocker alone will not adequately relieve established high-pressure retention with acute kidney injury and hyperkalaemia; catheter decompression is required immediately, not a delayed medical trial.', 1),
('d5000000-0000-0000-0000-000000000002', 'B', 'Restrict fluids and repeat renal function tomorrow', false, 'Ruled out because the obstruction itself, not volume overload, is driving the renal impairment; fluid restriction does not address the underlying obstructive uropathy and delays definitive treatment that is needed now.', 2),
('d5000000-0000-0000-0000-000000000002', 'C', 'Arrange outpatient urology review within two weeks', false, 'Ruled out because this represents an acute obstructive AKI with hyperkalaemia, which requires same-day intervention (catheterisation) rather than deferred outpatient assessment.', 3),
('d5000000-0000-0000-0000-000000000002', 'D', 'Urgent urethral catheterisation, followed by monitoring for post-obstructive diuresis', true, 'Correct. This presentation is high-pressure chronic retention with overflow incontinence causing obstructive (post-renal) acute kidney injury and hyperkalaemia. Urgent catheterisation is required to relieve the obstruction and protect renal function. Following decompression, urine output must be monitored closely as post-obstructive diuresis can cause large fluid and electrolyte losses requiring careful replacement, and renal function should be rechecked serially as it typically improves once the obstruction is relieved.', 4),
('d5000000-0000-0000-0000-000000000002', 'E', 'Give calcium resonium alone to manage the hyperkalaemia without catheterisation', false, 'Ruled out because treating hyperkalaemia in isolation ignores its reversible underlying cause; relieving the obstruction with a catheter is the definitive treatment, after which the hyperkalaemia and renal function typically improve without needing prolonged potassium-binding therapy.', 5),
('d5000000-0000-0000-0000-000000000003', 'A', 'Start oral trimethoprim for a 7-day course', false, 'Ruled out because treating asymptomatic bacteriuria in a catheterised patient provides no clinical benefit, does not reduce future symptomatic infections, and contributes to antimicrobial resistance and Clostridioides difficile risk.', 1),
('d5000000-0000-0000-0000-000000000003', 'B', 'Change the catheter and start antibiotics simultaneously', false, 'Ruled out because in the absence of symptoms there is no indication for antibiotics; routine catheter changes are not driven by asymptomatic bacteriuria results and should follow a scheduled maintenance plan rather than being triggered by a urine dipstick or culture.', 2),
('d5000000-0000-0000-0000-000000000003', 'C', 'No antibiotic treatment; continue routine catheter care', true, 'Correct. Bacteriuria is universal in patients with long-term indwelling catheters and does not itself indicate infection requiring treatment. In the absence of systemic or localising symptoms (fever, new confusion, loin or suprapubic tenderness, rigors), this represents catheter-associated asymptomatic bacteriuria, which should not be treated with antibiotics as this only promotes antimicrobial resistance without clinical benefit.', 3),
('d5000000-0000-0000-0000-000000000003', 'D', 'Send blood cultures and start intravenous antibiotics as this represents catheter-associated urosepsis', false, 'Ruled out because the patient is afebrile, haemodynamically stable and has no systemic or localising features of infection; this picture does not meet criteria for sepsis or symptomatic UTI, so escalation to intravenous antibiotics and blood cultures is not warranted.', 4),
('d5000000-0000-0000-0000-000000000003', 'E', 'Add prophylactic antibiotics to prevent future catheter-associated infections', false, 'Ruled out because prophylactic antibiotics in long-term catheterised patients are not recommended; they do not meaningfully reduce symptomatic infection rates and drive resistance, and asymptomatic bacteriuria itself should not be treated.', 5),
('d5000000-0000-0000-0000-000000000004', 'A', 'Oxybutynin', false, 'Ruled out because oxybutynin and other antimuscarinics are used for urgency incontinence and detrusor overactivity, not stress incontinence, which is due to sphincteric/pelvic floor weakness; they would not address her underlying mechanism of leakage.', 1),
('d5000000-0000-0000-0000-000000000004', 'B', 'Duloxetine', true, $x$Correct. Duloxetine, a serotonin-noradrenaline reuptake inhibitor, is licensed as an option for moderate to severe stress urinary incontinence in women who are not candidates for surgery, or who decline it. It works by increasing urethral sphincter tone via enhanced pudendal nerve (Onuf's nucleus) activity. It should be introduced with a gradual dose titration to reduce nausea, and used cautiously given her cardiac comorbidity, but is the appropriate pharmacological option here given she is unsuitable for surgery.$x$, 2),
('d5000000-0000-0000-0000-000000000004', 'C', 'Mirabegron', false, 'Ruled out because mirabegron is licensed for overactive bladder/urgency incontinence via detrusor relaxation, not for stress incontinence, and would not be expected to improve sphincteric leakage on exertion.', 3),
('d5000000-0000-0000-0000-000000000004', 'D', 'Referral for insertion of a mid-urethral sling despite the anaesthetic risk', false, 'Ruled out because she has already been assessed by the anaesthetic and urogynaecology teams as unfit for a surgical continence procedure given her severe aortic stenosis and poorly controlled atrial fibrillation; proceeding to surgery against this assessment would expose her to unacceptable perioperative risk when a pharmacological alternative exists.', 4),
('d5000000-0000-0000-0000-000000000004', 'E', 'Topical vaginal oestrogen alone as definitive treatment', false, 'Ruled out because topical vaginal oestrogen can help with urogenital atrophy symptoms and some overactive bladder symptoms, but is not an effective definitive treatment for stress incontinence due to sphincteric weakness, and would not be expected to substantially improve her leakage.', 5),
('d5000000-0000-0000-0000-000000000005', 'A', 'Start a high-dose oral macrogol (polyethylene glycol) disimpaction regimen', true, 'Correct. This presentation of watery soiling with a palpably loaded rectum and a background of constipation is overflow (spurious) diarrhoea due to faecal impaction, where liquid stool leaks around an obstructing faecal mass. The correct treatment is disimpaction using a high-dose oral macrogol regimen (with escalation and, if needed, addition of a stimulant laxative or rectal measures if oral treatment fails), not anti-diarrhoeal therapy.', 1),
('d5000000-0000-0000-0000-000000000005', 'B', 'Start loperamide to control the diarrhoea', false, 'Ruled out because loperamide is an anti-motility agent that would worsen faecal impaction by further slowing colonic transit, exacerbating rather than resolving the underlying problem.', 2),
('d5000000-0000-0000-0000-000000000005', 'C', 'Send a stool sample for Clostridioides difficile toxin and start empirical oral vancomycin', false, 'Ruled out because the clinical picture (chronic constipation, loaded rectum, palpable faecal mass) is characteristic of overflow diarrhoea from impaction rather than an infective colitis; while a stool sample may reasonably be sent to exclude infection, empirical antibiotic treatment for presumed C. difficile is not indicated here and would not address the underlying impaction.', 3),
('d5000000-0000-0000-0000-000000000005', 'D', 'Restrict oral fluids until the diarrhoea settles', false, 'Ruled out because fluid restriction does not treat faecal impaction and risks dehydration in an older patient; adequate hydration supports rather than hinders disimpaction.', 4),
('d5000000-0000-0000-0000-000000000005', 'E', 'Arrange urgent CT colonography to look for a colonic malignancy before treating', false, 'Ruled out because the clinical findings (loaded rectum, known chronic constipation, mobile non-tender mass consistent with faecal loading) support impaction as the primary diagnosis, which should be treated first; imaging can be considered subsequently if symptoms fail to resolve after disimpaction or if red-flag features persist, but should not delay first-line treatment.', 5),
('d5000000-0000-0000-0000-000000000006', 'A', 'Continue bed rest for a further week to allow full recovery before mobilising', false, 'Ruled out because prolonged bed rest is itself a major cause of further deconditioning, muscle loss and functional decline in older patients, and delaying mobilisation once a patient is medically stable increases the risk of a new care dependency.', 1),
('d5000000-0000-0000-0000-000000000006', 'B', 'Arrange discharge to a nursing home given his new care needs', false, 'Ruled out because his functional decline appears to be a reversible consequence of acute illness and hospital-associated deconditioning rather than an established new baseline; premature long-term care placement without first attempting rehabilitation risks an unnecessary and potentially irreversible loss of independence.', 2),
('d5000000-0000-0000-0000-000000000006', 'C', 'Continue the urinary catheter for comfort and to reduce nursing workload', false, 'Ruled out because the indication for catheterisation (output monitoring during AKI) has resolved, and an unnecessary indwelling catheter increases infection risk, restricts mobility and contributes to deconditioning; catheters should be removed as soon as they are no longer clinically indicated.', 3),
('d5000000-0000-0000-0000-000000000006', 'D', 'Remove the urinary catheter, initiate comprehensive geriatric assessment, and start structured daily physiotherapy-led mobilisation', true, 'Correct. Hospital-associated deconditioning is a major driver of functional decline in older inpatients, and its risk is compounded by avoidable immobilising factors such as an unnecessary indwelling catheter. Comprehensive geriatric assessment identifies and addresses the multiple contributing factors (medical, functional, psychological, social), while removing the catheter and instituting structured, progressive physiotherapy-led mobilisation as soon as medically stable is the key intervention to reverse deconditioning and restore baseline function.', 4),
('d5000000-0000-0000-0000-000000000006', 'E', 'Refer for permanent residential care placement without a trial of rehabilitation', false, 'Ruled out for the same reason as nursing home discharge: functional decline related to acute illness and inactivity should first be addressed with a structured rehabilitation trial (e.g., through a reablement or intermediate care pathway) before assuming it represents a permanent new baseline.', 5),
('d5000000-0000-0000-0000-000000000007', 'A', 'Proceed directly to ventriculoperitoneal shunt insertion without further testing', false, 'Ruled out because not all patients with the clinical triad and suggestive imaging respond to shunting, and proceeding directly to surgery without a predictive test exposes patients who would not benefit to unnecessary surgical risk; a CSF drainage trial (large-volume lumbar puncture or extended lumbar drainage) is used first to help select suitable candidates.', 1),
('d5000000-0000-0000-0000-000000000007', 'B', 'Perform a large-volume (therapeutic) lumbar puncture and assess for objective improvement in gait', true, 'Correct. This is the classic triad of normal pressure hydrocephalus (gait disturbance, urinary incontinence, cognitive impairment) with supportive imaging showing disproportionate ventriculomegaly. Before proceeding to ventriculoperitoneal shunt surgery, a large-volume (therapeutic) lumbar puncture, removing approximately 30-50ml of CSF with formal pre- and post-procedure gait assessment, is used to predict which patients are likely to benefit from shunting, since response to CSF drainage is the best available predictor of surgical benefit.', 2),
('d5000000-0000-0000-0000-000000000007', 'C', $x$Start a cholinesterase inhibitor for presumed Alzheimer's disease$x$, false, $x$Ruled out because the clinical and radiological picture here is characteristic of normal pressure hydrocephalus, a potentially reversible cause of gait disturbance and cognitive impairment, rather than Alzheimer's disease; treating this as Alzheimer's would miss the opportunity for a potentially effective intervention (shunting) and cholinesterase inhibitors have no proven role here.$x$, 3),
('d5000000-0000-0000-0000-000000000007', 'D', 'Reassure the patient that this represents normal age-related change and no intervention is required', false, 'Ruled out because the described triad with disproportionate ventriculomegaly on imaging represents a recognised, at least partially treatable, neurological syndrome, not normal ageing, and warrants further assessment for a CSF drainage trial rather than reassurance alone.', 4),
('d5000000-0000-0000-0000-000000000007', 'E', $x$Start levodopa for presumed Parkinson's disease given the gait disturbance$x$, false, $x$Ruled out because there is no tremor, rigidity or bradykinesia described to support Parkinson's disease, and the combination of gait apraxia, urinary incontinence and cognitive slowing with this MRI appearance points to normal pressure hydrocephalus rather than a Parkinsonian syndrome; a trial of levodopa is not the appropriate next diagnostic step.$x$, 5),
('d5000000-0000-0000-0000-000000000008', 'A', 'Continue tamsulosin at the same dose, as first-dose hypotension typically only occurs once', false, 'Ruled out because although first-dose hypotension is a recognised phenomenon, ongoing symptomatic postural hypotension with a fall indicates clinically significant harm has already occurred, particularly in the context of concurrent antihypertensive therapy, so it should not simply be continued unmodified without reassessment.', 1),
('d5000000-0000-0000-0000-000000000008', 'B', 'Increase ramipril to improve blood pressure control', false, 'Ruled out because his problem is hypotension causing a fall, not undertreated hypertension; increasing ramipril would worsen his orthostatic drop and further increase falls risk.', 2),
('d5000000-0000-0000-0000-000000000008', 'C', 'Withhold further tamsulosin and review his antihypertensive regimen', true, 'Correct. Tamsulosin, an alpha-1 adrenoceptor antagonist, can cause significant first-dose and ongoing postural hypotension, particularly when combined with other antihypertensive agents such as amlodipine and ramipril. Given a symptomatic fall with a marked orthostatic drop, tamsulosin should be withheld and his overall antihypertensive burden reviewed, with consideration of alternative BPH management (e.g., a 5-alpha reductase inhibitor if appropriate, or non-pharmacological/urological options) once he is stabilised.', 3),
('d5000000-0000-0000-0000-000000000008', 'D', 'Start fludrocortisone immediately to counteract the hypotension while continuing tamsulosin', false, 'Ruled out because the more appropriate and lower-risk first step is to remove or reduce the likely causative and non-essential drug (tamsulosin, alongside reviewing other antihypertensives) rather than adding a mineralocorticoid, which carries its own risks (fluid retention, heart failure, hypokalaemia) and should not be first-line here.', 4),
('d5000000-0000-0000-0000-000000000008', 'E', 'Advise strict bed rest until symptoms resolve', false, 'Ruled out because prolonged bed rest in an older patient increases the risk of deconditioning, venous thromboembolism and further functional decline, and does not address the underlying cause of his hypotension; safe mobilisation with medication review is the appropriate approach.', 5),
('d5000000-0000-0000-0000-000000000009', 'A', 'Increase the furosemide dose to improve diuretic efficiency', false, 'Ruled out because increasing the dose would worsen nocturnal urine output and falls risk, without evidence that her heart failure requires dose escalation; the problem here is timing, not inadequate diuresis.', 1),
('d5000000-0000-0000-0000-000000000009', 'B', 'Stop furosemide altogether given her stable heart failure', false, 'Ruled out because abruptly stopping a diuretic that is maintaining stable heart failure control risks decompensation and fluid overload; the appropriate response to a timing-related side effect is to adjust timing, not withdraw a clinically indicated medication.', 2),
('d5000000-0000-0000-0000-000000000009', 'C', 'Restrict all fluid intake after midday', false, 'Ruled out because significant daytime fluid restriction in an older person risks dehydration and does not address the underlying pharmacological cause (evening diuretic dosing); adjusting the timing of the diuretic is the more appropriate and specific intervention.', 3),
('d5000000-0000-0000-0000-000000000009', 'D', 'Prescribe a bedside commode without changing medication timing', false, 'Ruled out because while environmental modifications can reduce fall-related injury, they do not address the underlying reversible cause of her nocturia; the priority is to correct the modifiable drug-related cause first.', 4),
('d5000000-0000-0000-0000-000000000009', 'E', 'Change the timing of furosemide to the morning', true, 'Correct. Evening dosing of a loop diuretic is a common and easily reversible cause of nocturnal polyuria, leading to disturbed sleep and falls risk from repeated night-time transfers in the dark. Moving the dose to the morning (or early afternoon, if a second daily dose is needed) allows diuresis to occur during waking hours while maintaining the same total daily dose and heart failure control.', 5),
('d5000000-0000-0000-0000-000000000010', 'A', 'Direct further treatment towards her stress incontinence component, as this is her predominant and most bothersome symptom', true, 'Correct. In mixed urinary incontinence, management should be individualised and directed towards the component that is most bothersome to the patient, since treating only the urge component (as has already been attempted with pelvic floor training and would be the target of antimuscarinics or mirabegron) will not address her main source of distress. As she has an identified predominant stress component causing greater bother, options addressing stress incontinence (further pelvic floor optimisation, duloxetine, or surgical referral if appropriate) should now be prioritised.', 1),
('d5000000-0000-0000-0000-000000000010', 'B', 'Start an antimuscarinic, since urgency incontinence is usually the dominant driver in mixed incontinence', false, $x$Ruled out because it is not correct to assume urgency is always dominant in mixed incontinence; this patient's own report and urodynamic findings identify a predominant, more bothersome stress component, and treatment should be tailored to the individual patient's predominant and most bothersome symptom rather than a generic assumption.$x$, 2),
('d5000000-0000-0000-0000-000000000010', 'C', 'Recommend an indwelling catheter to manage both components definitively', false, 'Ruled out because an indwelling catheter is not an appropriate treatment for either stress or urge incontinence in a mobile, cognitively intact woman; it carries substantial risks (infection, reduced mobility) and is reserved for very different indications such as retention.', 3),
('d5000000-0000-0000-0000-000000000010', 'D', 'Reassure her that no further treatment is available since she has already tried pelvic floor training', false, 'Ruled out because further options exist for the stress component of her incontinence, including continued pelvic floor optimisation, duloxetine, or surgical referral, and she should not be told no further treatment is possible.', 4),
('d5000000-0000-0000-0000-000000000010', 'E', 'Refer for botulinum toxin bladder injections as first-line treatment', false, 'Ruled out because intravesical botulinum toxin is used for refractory urgency incontinence/detrusor overactivity after failure of oral antimuscarinic or beta-3 agonist therapy, not as a first-line option, and would not address her predominant stress component in any case.', 5),
('d5000000-0000-0000-0000-000000000011', 'A', 'Physical restraint as the primary management strategy', false, 'Ruled out because physical restraint is associated with increased agitation, injury, and prolongation of delirium, and should be avoided as a primary strategy; pharmacological management is preferred when non-pharmacological measures have failed and there is a genuine safety risk.', 1),
('d5000000-0000-0000-0000-000000000011', 'B', 'A short course of low-dose oral or intramuscular haloperidol', true, 'Correct. When non-pharmacological measures have been properly tried and reversible causes addressed, but a patient with delirium remains severely agitated and poses a risk of harm to themselves or others, a short course of low-dose haloperidol is recommended as per national guidance, provided there are no contraindications such as Parkinsonism, Lewy body dementia or significant QT prolongation, which this patient does not have. It should be used at the lowest effective dose for the shortest possible time, with cardiac and extrapyramidal monitoring.', 2),
('d5000000-0000-0000-0000-000000000011', 'C', 'High-dose intravenous lorazepam as first-line sedation', false, 'Ruled out because benzodiazepines can worsen delirium (except in alcohol/benzodiazepine withdrawal or where antipsychotics are contraindicated) due to their sedative and disinhibiting effects, and are not first-line for managing agitation in delirium without such a specific indication.', 3),
('d5000000-0000-0000-0000-000000000011', 'D', 'Commence donepezil to improve cognitive symptoms acutely', false, 'Ruled out because cholinesterase inhibitors have no established role in the acute management of delirium and would not address her immediate agitation and safety risk.', 4),
('d5000000-0000-0000-0000-000000000011', 'E', 'Continue non-pharmacological measures alone, as pharmacological treatment is never indicated in delirium', false, 'Ruled out because although non-pharmacological measures are first-line and should always be attempted first, guidance clearly supports short-term low-dose antipsychotic treatment when these measures have failed and there is significant risk of harm, as in this case.', 5),
('d5000000-0000-0000-0000-000000000012', 'A', 'Start haloperidol at standard delirium doses, as in any other agitated older patient', false, 'Ruled out because haloperidol carries a particularly high risk of severe, sometimes irreversible or fatal, neuroleptic sensitivity reactions in dementia with Lewy bodies, and should be avoided in this population even though it might be considered in a patient without this diagnosis.', 1),
('d5000000-0000-0000-0000-000000000012', 'B', 'Use risperidone at standard BPSD doses without additional caution', false, 'Ruled out because although risperidone is licensed for behavioural symptoms in dementia generally, patients with dementia with Lewy bodies remain at increased risk of neuroleptic sensitivity with any antipsychotic, and treatment (if required at all) should be at the lowest possible dose with heightened monitoring, not standard unmodified dosing.', 2),
('d5000000-0000-0000-0000-000000000012', 'C', 'Reassure the family that antipsychotics are absolutely contraindicated and no drug treatment can ever be offered', false, 'Ruled out because while antipsychotics carry substantial risk in dementia with Lewy bodies and should be avoided where possible, they are not absolutely contraindicated; a very low-dose atypical agent can be used with caution when distress is severe and non-pharmacological measures have failed, so blanket refusal of any drug treatment is incorrect.', 3),
('d5000000-0000-0000-0000-000000000012', 'D', 'Avoid conventional antipsychotics such as haloperidol; if drug treatment is unavoidable, use a low dose of an atypical agent such as quetiapine with very close monitoring', true, 'Correct. Patients with dementia with Lewy bodies are at high risk of severe neuroleptic sensitivity reactions to antipsychotics, particularly typical agents like haloperidol, which can cause acute and severe worsening of Parkinsonism, autonomic instability, and even be life-threatening. Where non-pharmacological approaches are insufficient and treatment cannot be avoided, a low-dose atypical antipsychotic with a lower propensity for extrapyramidal effects, such as quetiapine, is preferred, started at the lowest possible dose with very close monitoring for adverse reactions.', 4),
('d5000000-0000-0000-0000-000000000012', 'E', 'Start clozapine as first-line therapy given the diagnosis', false, $x$Ruled out because although clozapine has a lower risk of extrapyramidal effects and is used in Parkinson's disease psychosis, it requires mandatory haematological monitoring and specialist initiation, and is not the appropriate first-line choice in this acute general hospital setting compared with a low-dose atypical such as quetiapine.$x$, 5),
('d5000000-0000-0000-0000-000000000013', 'A', 'Stop donepezil and arrange cardiology assessment', true, 'Correct. Cholinesterase inhibitors increase vagal (parasympathetic) tone and can cause bradycardia, syncope, and conduction abnormalities including atrioventricular block, particularly at higher doses. Given her symptomatic bradycardia and new higher-grade conduction disturbance temporally related to dose escalation, donepezil should be stopped and she should have cardiology assessment, with consideration of whether the conduction abnormality resolves after discontinuation before deciding on any future cognitive treatment strategy.', 1),
('d5000000-0000-0000-0000-000000000013', 'B', 'Continue donepezil at the same dose and monitor heart rate daily', false, 'Ruled out because continuing a drug that is very likely causing symptomatic bradycardia and progressive conduction disease risks further deterioration, potential complete heart block, or recurrent syncope with associated fall risk; the drug should be stopped, not continued unmodified.', 2),
('d5000000-0000-0000-0000-000000000013', 'C', 'Reduce the dose back to 5mg daily without cardiology input', false, 'Ruled out because although dose reduction can sometimes be considered for milder cholinesterase inhibitor side effects, in the context of symptomatic bradycardia with new higher-grade AV block, the more appropriate and safer step is to stop the drug altogether and obtain cardiology assessment, given the risk of progression to complete heart block.', 3),
('d5000000-0000-0000-0000-000000000013', 'D', 'Start atropine prophylactically and continue donepezil', false, 'Ruled out because prophylactic atropine is not appropriate ongoing management for a reversible drug-induced conduction abnormality; the priority is to remove the causative agent, not to mask its effect with an anticholinergic while continuing the cholinesterase inhibitor.', 4),
('d5000000-0000-0000-0000-000000000013', 'E', 'Switch immediately to memantine at full dose without stopping donepezil first', false, 'Ruled out because adding memantine does not address the acute cardiac issue caused by donepezil, and donepezil should be stopped first; memantine has a different mechanism (NMDA receptor antagonism) without the same vagotonic cardiac effects, but this does not justify continuing donepezil in the interim.', 5),
('d5000000-0000-0000-0000-000000000014', 'A', 'Long-term regular risperidone with no planned review, as his symptoms are unlikely to improve', false, 'Ruled out because antipsychotics in dementia should be used for the shortest time necessary with regular review (typically within 6 weeks) given their association with increased stroke risk and mortality; open-ended treatment without review is not appropriate.', 1),
('d5000000-0000-0000-0000-000000000014', 'B', 'Chlorpromazine as first-line therapy', false, 'Ruled out because chlorpromazine is not the recommended or licensed choice for BPSD; it carries a high anticholinergic and sedative burden and significant risk of postural hypotension and extrapyramidal effects in older patients, and is not preferred over risperidone in this context.', 2),
('d5000000-0000-0000-0000-000000000014', 'C', 'Risperidone at the lowest effective dose, reviewed after a maximum of 6 weeks', true, $x$Correct. Risperidone is the only antipsychotic licensed in the UK for short-term treatment (up to 6 weeks) of persistent aggression in Alzheimer's and vascular dementia unresponsive to non-pharmacological approaches. It should be used at the lowest effective dose for the shortest duration necessary, with regular review, because of the recognised increased risk of stroke and all-cause mortality with antipsychotic use in dementia, and because non-pharmacological approaches have already been appropriately trialled and failed here.$x$, 3),
('d5000000-0000-0000-0000-000000000014', 'D', 'A benzodiazepine such as lorazepam as first-line regular treatment for his aggression', false, 'Ruled out because benzodiazepines are not first-line for chronic behavioural and psychological symptoms of dementia; they carry risks of sedation, falls, paradoxical disinhibition and dependence, and are generally reserved for acute severe crisis situations rather than regular ongoing management.', 4),
('d5000000-0000-0000-0000-000000000014', 'E', 'No pharmacological treatment should ever be offered in dementia-related agitation', false, 'Ruled out because while non-pharmacological approaches are always first-line and were appropriately tried here, guidance supports short-term, carefully monitored use of risperidone when these measures fail and there is significant risk or distress, as in this case.', 5),
('d5000000-0000-0000-0000-000000000015', 'A', 'Increase the dose of a cholinesterase inhibitor to counteract the anticholinergic effects', false, $x$Ruled out because increasing a cholinesterase inhibitor dose to 'counteract' ongoing anticholinergic drug exposure treats a symptom pharmacologically rather than removing the reversible cause, and does not address the cumulative anticholinergic burden driving her decline; deprescribing the anticholinergic drugs themselves is the appropriate step.$x$, 1),
('d5000000-0000-0000-0000-000000000015', 'B', 'Attribute the cognitive change entirely to disease progression and make no medication changes', false, 'Ruled out because there is a clear, reversible, and modifiable contributor here (cumulative anticholinergic burden), and it would be inappropriate to attribute her decline solely to dementia progression without first addressing this.', 2),
('d5000000-0000-0000-0000-000000000015', 'C', 'Add memantine without reviewing her current anticholinergic medications', false, 'Ruled out because starting an additional drug without first addressing the likely reversible cause of her worsening cognition does not represent good prescribing practice, and would leave her exposed to ongoing anticholinergic harm.', 3),
('d5000000-0000-0000-0000-000000000015', 'D', 'Continue all current medications unchanged, as they were each started for a valid original indication', false, 'Ruled out because a valid original indication does not mean a medication remains appropriate indefinitely; ongoing anticholinergic burden should be reassessed periodically, especially when there is evidence of associated harm such as accelerated cognitive decline.', 4),
('d5000000-0000-0000-0000-000000000015', 'E', 'Systematically review and deprescribe unnecessary anticholinergic medications', true, 'Correct. Oxybutynin, amitriptyline and chlorphenamine are all agents with significant anticholinergic activity, and their cumulative anticholinergic burden is a recognised, reversible contributor to accelerated cognitive decline and confusion in older people with dementia. The most appropriate step is a structured medication review to identify and stop or substitute unnecessary anticholinergic drugs (for example, considering mirabegron instead of oxybutynin, and non-anticholinergic alternatives for pain and itch), rather than attributing the decline solely to disease progression.', 5),
('d5000000-0000-0000-0000-000000000016', 'A', 'Start haloperidol immediately to control her agitation', false, 'Ruled out because pharmacological treatment for delirium-related agitation should only be considered after reversible precipitants have been assessed and addressed and non-pharmacological measures attempted; jumping to an antipsychotic without first excluding urinary retention, constipation, and other treatable causes risks masking a treatable problem.', 1),
('d5000000-0000-0000-0000-000000000016', 'B', 'Increase her co-codamol dose, assuming her agitation reflects undertreated pain', false, 'Ruled out because increasing an opioid-containing analgesic without first clarifying the cause of her distress risks worsening delirium (opioids are a recognised precipitant/aggravating factor) and does not address the more likely reversible causes of urinary retention and constipation that need urgent assessment.', 2),
('d5000000-0000-0000-0000-000000000016', 'C', 'Arrange an urgent CT head as the first investigation', false, 'Ruled out because in the absence of focal neurological signs, head injury, or anticoagulation, urgent CT head is not the first-line investigation for postoperative delirium; assessment for common reversible precipitants (retention, constipation, infection, metabolic derangement, drug effects) should occur first.', 3),
('d5000000-0000-0000-0000-000000000016', 'D', 'Perform a bladder scan and examine for faecal loading, alongside full reassessment for other reversible causes, before considering any pharmacological treatment for agitation', true, 'Correct. Postoperative delirium is common after hip fracture surgery and is frequently driven by identifiable and reversible precipitants such as urinary retention, constipation, pain, infection, hypoxia, and electrolyte disturbance. A bladder scan (to assess for retention, particularly given no urine output for 10 hours) and assessment for faecal impaction (given no bowel movement for 5 days) should be performed alongside a full systematic reassessment for other reversible causes as the priority first step, before considering pharmacological treatment for agitation.', 4),
('d5000000-0000-0000-0000-000000000016', 'E', 'Apply physical restraints to prevent her from getting out of bed until she settles', false, 'Ruled out because physical restraint increases agitation and the risk of injury and is not an appropriate initial management strategy; addressing reversible causes and using non-pharmacological de-escalation should be prioritised.', 5),
('d5000000-0000-0000-0000-000000000017', 'A', 'Chlordiazepoxide at standard starting doses', false, 'Ruled out because chlordiazepoxide undergoes extensive hepatic oxidative metabolism and has active metabolites with long half-lives; in significant hepatic impairment this can lead to drug accumulation, oversedation, and precipitation of hepatic encephalopathy, making it a less safe choice here.', 1),
('d5000000-0000-0000-0000-000000000017', 'B', 'Lorazepam', true, 'Correct. In patients with significant hepatic impairment, benzodiazepines that are metabolised primarily by hepatic oxidation (such as chlordiazepoxide and diazepam) can accumulate due to reduced clearance and active metabolites, risking oversedation and precipitating hepatic encephalopathy. Lorazepam is metabolised by glucuronidation, a pathway that is relatively preserved in cirrhosis, and lacks active metabolites, making it a safer choice for symptom-triggered alcohol withdrawal treatment in this patient with Child-Pugh B cirrhosis.', 2),
('d5000000-0000-0000-0000-000000000017', 'C', 'Diazepam at standard starting doses', false, 'Ruled out because, like chlordiazepoxide, diazepam is metabolised via hepatic oxidation to active metabolites with prolonged half-lives, and its use in significant hepatic impairment risks accumulation and oversedation.', 3),
('d5000000-0000-0000-0000-000000000017', 'D', 'No benzodiazepine treatment, using only intravenous thiamine', false, $x$Ruled out because thiamine (to prevent Wernicke's encephalopathy) is essential but does not treat the alcohol withdrawal syndrome itself; benzodiazepine treatment remains the mainstay of managing delirium tremens and untreated withdrawal can progress to seizures or fatal delirium tremens.$x$, 4),
('d5000000-0000-0000-0000-000000000017', 'E', 'Haloperidol alone as monotherapy for the withdrawal syndrome', false, 'Ruled out because haloperidol does not treat the underlying GABAergic withdrawal state and, importantly, lowers the seizure threshold; it is not a substitute for benzodiazepine treatment in alcohol withdrawal, though it may occasionally be used adjunctively for severe hallucinations if agitation persists despite adequate benzodiazepine dosing.', 5),
('d5000000-0000-0000-0000-000000000018', 'A', 'Cholinesterase inhibitors and memantine are not recommended in frontotemporal dementia, as evidence does not support benefit and they may worsen behavioural symptoms in some patients', true, $x$Correct. Unlike Alzheimer's disease, frontotemporal dementia is not primarily associated with a cholinergic deficit, and clinical trial evidence does not support benefit from cholinesterase inhibitors or memantine in this condition; some studies suggest cholinesterase inhibitors may even worsen behavioural symptoms in a proportion of patients. Management of behavioural and psychological symptoms in frontotemporal dementia instead focuses on non-pharmacological strategies and, where needed, agents such as SSRIs, which have better evidence for reducing behavioural disturbance in this condition.$x$, 1),
('d5000000-0000-0000-0000-000000000018', 'B', 'Donepezil should be started immediately, as it is effective across all dementia subtypes', false, $x$Ruled out because donepezil's efficacy is established in Alzheimer's disease (and to some extent dementia with Lewy bodies/Parkinson's disease dementia), not frontotemporal dementia, where the underlying neurochemical deficit and evidence base differ, and it may worsen behavioural symptoms in some patients.$x$, 2),
('d5000000-0000-0000-0000-000000000018', 'C', 'Memantine should be used as first-line treatment given its different mechanism of action', false, 'Ruled out because memantine has not shown consistent benefit in frontotemporal dementia in clinical trials, and its use is not recommended as first-line (or routine) treatment in this condition.', 3),
('d5000000-0000-0000-0000-000000000018', 'D', 'Combination therapy with a cholinesterase inhibitor and memantine should be started to maximise benefit', false, 'Ruled out because neither drug class has an established evidence base for benefit in frontotemporal dementia, so combining them would not be expected to provide additional benefit and could expose the patient to unnecessary side effects.', 4),
('d5000000-0000-0000-0000-000000000018', 'E', 'No pharmacological treatment of any kind has a role in frontotemporal dementia', false, 'Ruled out because while cholinesterase inhibitors and memantine are not recommended, other pharmacological options (notably SSRIs) do have a role in managing behavioural and psychological symptoms of frontotemporal dementia, so it is incorrect to say no drug treatment has any role.', 5),
('d5000000-0000-0000-0000-000000000019', 'A', 'Start regular risperidone immediately as suggested, since her infection has been treated', false, 'Ruled out because it should not be assumed that resolution of the original precipitant means no reversible cause remains; a systematic reassessment for ongoing or new contributing factors should occur first, reserving antipsychotic treatment for cases where non-pharmacological measures and treatment of causes fail and there is significant risk or distress.', 1),
('d5000000-0000-0000-0000-000000000019', 'B', 'Repeat a further course of the same antibiotic empirically', false, 'Ruled out because her infective markers have normalised and urinary symptoms resolved, so there is no indication for further antibiotics without new evidence of infection; empirical re-treatment would not be appropriate antimicrobial stewardship.', 2),
('d5000000-0000-0000-0000-000000000019', 'C', 'Reassess systematically for other or persisting reversible causes of her ongoing confusion before considering antipsychotic treatment', true, 'Correct. Delirium can persist or fluctuate even after the initial precipitant (here, the urinary tract infection) has been treated, especially in a patient with underlying dementia, who is at higher baseline vulnerability and slower recovery. Before considering an antipsychotic, a full reassessment should be performed for other or ongoing contributing factors such as a new infection, pain, constipation, urinary retention, medication effects, sensory impairment, and environmental factors, since resolving these may improve her agitation without the need for drug treatment.', 3),
('d5000000-0000-0000-0000-000000000019', 'D', 'Discharge her to a nursing home as her cognition is unlikely to ever recover', false, 'Ruled out because delirium superimposed on dementia can take considerably longer than a few days to resolve, and premature assumptions about a permanent new baseline, with associated placement decisions, should be avoided until reversible factors have been excluded and adequate time for recovery has been allowed.', 4),
('d5000000-0000-0000-0000-000000000019', 'E', 'Increase her donepezil dose to help clear the confusion faster', false, 'Ruled out because cholinesterase inhibitors have no established role in accelerating recovery from an acute delirious episode, and dose escalation would not be expected to help and could cause additional side effects.', 5),
('d5000000-0000-0000-0000-000000000020', 'A', 'Stop all cholinesterase inhibitor treatment permanently', false, 'Ruled out because he has shown a clear cognitive benefit from cholinesterase inhibitor therapy, and there are formulation-based strategies (such as switching to a transdermal patch) that can address his tolerability issue without abandoning a treatment that is working for him.', 1),
('d5000000-0000-0000-0000-000000000020', 'B', 'Increase the donepezil dose further to overcome tolerance', false, 'Ruled out because increasing the dose of a drug causing dose-related gastrointestinal side effects would be expected to worsen, not improve, his nausea and vomiting.', 2),
('d5000000-0000-0000-0000-000000000020', 'C', 'Add an antiemetic such as metoclopramide for long-term co-prescription', false, 'Ruled out because metoclopramide carries extrapyramidal and neuroleptic-type risks, particularly in older patients, and is not appropriate as long-term co-therapy when a simpler, formulation-based solution (the rivastigmine patch) avoids the problem altogether without adding another drug and its associated risks.', 3),
('d5000000-0000-0000-0000-000000000020', 'D', 'Switch to memantine monotherapy in place of any cholinesterase inhibitor', false, 'Ruled out because memantine has a different mechanism, different indication profile (typically added in moderate-to-severe disease or when cholinesterase inhibitors are not tolerated at all), and switching away from a cholinesterase inhibitor that has shown clear benefit is not necessary when a better-tolerated formulation of a similar drug class exists.', 4),
('d5000000-0000-0000-0000-000000000020', 'E', 'Switch to a rivastigmine transdermal patch', true, 'Correct. Gastrointestinal side effects (nausea, vomiting) are common with oral cholinesterase inhibitors and are related to peak plasma drug concentrations. Switching to a transdermal rivastigmine patch avoids the sharp peaks seen with oral dosing, substantially reducing gastrointestinal side effects while maintaining comparable cognitive efficacy, making it an appropriate option for a patient benefiting cognitively but limited by GI tolerability on an oral agent.', 5),
('d5000000-0000-0000-0000-000000000021', 'A', 'Systematically review and reduce or stop medications contributing to postural hypotension', true, 'Correct. She has a clinically significant and symptomatic orthostatic blood pressure drop with several medications known to contribute to postural hypotension (amlodipine, a thiazide diuretic, and tamsulosin, an alpha-blocker). The most appropriate initial step is a structured medication review, reducing or stopping the most likely contributing and least essential agents (often starting with the alpha-blocker and/or diuretic, reviewing ongoing indication), before considering non-pharmacological or pharmacological treatments specifically for orthostatic hypotension.', 1),
('d5000000-0000-0000-0000-000000000021', 'B', 'Start fludrocortisone immediately without reviewing her current medications', false, 'Ruled out because the first and most appropriate step when postural hypotension is likely medication-related is to address the causative drugs; starting a mineralocorticoid (with risks of fluid retention, hypokalaemia, and supine hypertension) before attempting deprescribing is not the correct sequence.', 2),
('d5000000-0000-0000-0000-000000000021', 'C', 'Reassure her that this is a normal finding at her age and no action is needed', false, 'Ruled out because a 40 mmHg systolic and 18 mmHg diastolic drop reproducing her symptoms is a clinically significant and symptomatic finding requiring active management, not a normal incidental finding to be dismissed.', 3),
('d5000000-0000-0000-0000-000000000021', 'D', 'Increase her citalopram dose to treat presumed underlying anxiety causing her falls', false, 'Ruled out because there is no indication her falls are due to anxiety; her findings are explained by orthostatic hypotension related to her antihypertensive and alpha-blocker therapy, and increasing an SSRI dose would not address this and could itself contribute to hyponatraemia and falls risk.', 4),
('d5000000-0000-0000-0000-000000000021', 'E', 'Refer for permanent pacemaker insertion', false, 'Ruled out because her ECG shows normal sinus rhythm with no evidence of a bradyarrhythmia or conduction disease, and her presentation is explained by orthostatic hypotension rather than a cardiac rhythm disturbance requiring pacing.', 5),
('d5000000-0000-0000-0000-000000000022', 'A', 'Use the Clinical Frailty Scale score alone as an absolute cut-off to deny ICU admission regardless of other factors', false, 'Ruled out because although a high Clinical Frailty Scale score is associated with poorer outcomes and is a useful prognostic input, using it as a rigid, isolated cut-off without considering the whole clinical picture and patient/family wishes is not appropriate practice; decisions should be individualised.', 1),
('d5000000-0000-0000-0000-000000000022', 'B', 'Use the Clinical Frailty Scale as one important prognostic factor alongside overall clinical assessment and shared decision-making with the patient and family, rather than as the sole determinant', true, $x$Correct. The Clinical Frailty Scale is a validated tool that correlates with mortality and adverse outcomes, including in the context of critical illness, and a high score (such as 8, indicating very severe frailty with complete dependency) is associated with poor outcomes from intensive interventions such as ICU admission. However, it should be used as one part of a holistic assessment, considered alongside the severity and reversibility of the acute illness, comorbidities, and the patient's and family's wishes, through shared decision-making, rather than being used in isolation as a rigid cut-off to deny or mandate treatment.$x$, 2),
('d5000000-0000-0000-0000-000000000022', 'C', 'Do not use the Clinical Frailty Scale at all, as it has no validated role in acute illness', false, 'Ruled out because the Clinical Frailty Scale has a well-established evidence base as a prognostic tool in acutely unwell older adults, including in the context of decisions around escalation of care and critical care admission, so dismissing it entirely is incorrect.', 3),
('d5000000-0000-0000-0000-000000000022', 'D', 'Apply the Clinical Frailty Scale only after ICU admission has already occurred, to guide subsequent care', false, 'Ruled out because the scale is most useful when applied prospectively, at the point of assessing the appropriateness of escalation, to help inform shared decision-making before a decision about ICU admission is made, not merely retrospectively.', 4),
('d5000000-0000-0000-0000-000000000022', 'E', 'Base the ceiling of care entirely on his age rather than his frailty score or clinical assessment', false, 'Ruled out because chronological age alone is a poor predictor of outcome and should not be used as the primary determinant of treatment ceilings; frailty assessment and overall clinical judgement, incorporating patient wishes, are more appropriate and personalised measures.', 5),
('d5000000-0000-0000-0000-000000000023', 'A', 'Start midodrine to increase peripheral vascular resistance', false, 'Ruled out because midodrine is used for vasodepressor-type (blood pressure drop predominant) carotid sinus hypersensitivity or orthostatic hypotension, not the cardioinhibitory type demonstrated here, where the problem is a profound bradyarrhythmic pause rather than vasodilatation.', 1),
('d5000000-0000-0000-0000-000000000023', 'B', 'Advise him simply to avoid tight collars with no further intervention', false, 'Ruled out because although avoiding known mechanical triggers is sensible general advice, it does not address the underlying cardioinhibitory abnormality causing prolonged asystole, and definitive treatment with a pacemaker is indicated given the severity of the pause and symptom reproduction.', 2),
('d5000000-0000-0000-0000-000000000023', 'C', 'Referral for permanent pacemaker implantation', true, 'Correct. This is cardioinhibitory carotid sinus hypersensitivity, defined by carotid sinus massage producing a significant asystolic pause (conventionally greater than 3 seconds) with minimal vasodepressor (blood pressure) component, reproducing his syncopal/presyncopal symptoms. The definitive treatment for the cardioinhibitory subtype is permanent pacemaker implantation, which effectively reduces recurrent syncope and falls in this condition.', 3),
('d5000000-0000-0000-0000-000000000023', 'D', 'Start a beta-blocker to prevent recurrent syncope', false, 'Ruled out because beta-blockers would further slow atrioventricular conduction and heart rate, worsening rather than treating cardioinhibitory carotid sinus hypersensitivity, and are contraindicated in this context.', 4),
('d5000000-0000-0000-0000-000000000023', 'E', 'Reassure him that this is a benign finding of ageing requiring no treatment', false, 'Ruled out because a 4.2 second asystolic pause reproducing his symptoms represents a significant and treatable cause of recurrent falls and syncope, not a benign incidental finding, and warrants active treatment with pacing.', 5),
('d5000000-0000-0000-0000-000000000024', 'A', 'Regular oral betahistine', false, $x$Ruled out because betahistine is used mainly in Meniere's disease and provides only symptomatic benefit at best in BPPV; it does not address the underlying otolith displacement and is not first-line treatment compared with a physical repositioning manoeuvre.$x$, 1),
('d5000000-0000-0000-0000-000000000024', 'B', 'Vestibular suppressant such as prochlorperazine on a regular basis', false, 'Ruled out because vestibular suppressants provide only symptomatic relief, can cause sedation and extrapyramidal side effects (particularly relevant in older patients), and are not as effective as the Epley manoeuvre for treating BPPV; they are not recommended for regular long-term use in this condition.', 2),
('d5000000-0000-0000-0000-000000000024', 'C', 'Urgent MRI brain to exclude a central cause before considering treatment', false, 'Ruled out because her history and examination (brief positional vertigo, classic fatiguing torsional nystagmus on Dix-Hallpike, absence of other neurological signs) are entirely consistent with peripheral BPPV, and urgent MRI is not required before starting first-line treatment in this typical presentation.', 3),
('d5000000-0000-0000-0000-000000000024', 'D', 'Epley manoeuvre (particle repositioning)', true, 'Correct. The history of brief positional vertigo triggered by specific head movements, with a positive Dix-Hallpike test showing the characteristic fatiguing torsional-upbeating nystagmus, confirms benign paroxysmal positional vertigo affecting the posterior semicircular canal. The Epley manoeuvre, a canalith repositioning procedure, is the recommended first-line treatment and is more effective than vestibular suppressant medication, with a high success rate in resolving symptoms.', 4),
('d5000000-0000-0000-0000-000000000024', 'E', 'Vestibular rehabilitation exercises alone, without any repositioning manoeuvre', false, 'Ruled out because while vestibular rehabilitation exercises can have an adjunctive role, particularly for residual imbalance, the Epley manoeuvre is the specific, more immediately effective first-line treatment for posterior canal BPPV and should be offered rather than being omitted in favour of general exercises alone.', 5),
('d5000000-0000-0000-0000-000000000025', 'A', 'High-dose vitamin D supplementation alone', false, 'Ruled out because although correcting vitamin D deficiency is appropriate where present, vitamin D supplementation alone has not been shown to reliably reverse sarcopenia or frailty, and is not as effective as a combined exercise and nutritional protein intervention.', 1),
('d5000000-0000-0000-0000-000000000025', 'B', 'Testosterone replacement therapy as first-line treatment', false, 'Ruled out because testosterone therapy is not a standard or recommended first-line treatment for frailty or sarcopenia in this context, given an unfavourable risk-benefit profile in older adults and lack of robust evidence supporting its routine use for this indication.', 2),
('d5000000-0000-0000-0000-000000000025', 'C', 'Strict bed rest to conserve her energy and prevent further falls', false, 'Ruled out because bed rest accelerates muscle loss and functional decline and would worsen her frailty and sarcopenia; activity and resistance exercise, not rest, are the evidence-based intervention.', 3),
('d5000000-0000-0000-0000-000000000025', 'D', 'Referral for immediate residential care placement', false, 'Ruled out because she remains independently living, and frailty is a dynamic state that can be improved with targeted exercise and nutritional intervention; moving straight to residential care without attempting evidence-based rehabilitation is premature and not appropriate.', 4),
('d5000000-0000-0000-0000-000000000025', 'E', 'A structured programme of progressive resistance exercise combined with adequate dietary protein intake', true, 'Correct. She meets the Fried frailty phenotype criteria (unintentional weight loss, exhaustion, weakness, slow gait speed, low activity), which reflects underlying sarcopenia and reduced physiological reserve. The intervention with the strongest evidence base for improving muscle strength, function and frailty status is a structured programme of progressive resistance exercise, combined with ensuring adequate dietary protein intake to support muscle protein synthesis, delivered as part of a comprehensive geriatric assessment approach.', 5),
('d5000000-0000-0000-0000-000000000026', 'A', 'Advise her to remain at home and avoid walking until her confidence returns spontaneously', false, 'Ruled out because avoiding activity perpetuates the deconditioning-fear cycle and increases, rather than reduces, future falls risk; active rehabilitation, not avoidance, is the appropriate management.', 1),
('d5000000-0000-0000-0000-000000000026', 'B', 'Prescribe a benzodiazepine to reduce her anxiety about falling', false, 'Ruled out because benzodiazepines are strongly associated with increased falls risk in older people due to sedation, impaired balance and cognitive effects, and would be expected to worsen rather than improve her situation.', 2),
('d5000000-0000-0000-0000-000000000026', 'C', 'Arrange for permanent use of a wheelchair to prevent further falls', false, 'Ruled out because she remains ambulant with no new medical cause found, and permanently removing her ability to walk would accelerate deconditioning and loss of independence rather than address the underlying, modifiable fear of falling and deconditioning.', 3),
('d5000000-0000-0000-0000-000000000026', 'D', 'Referral to a structured, individualised strength and balance training programme (such as the Otago exercise programme)', true, 'Correct. Fear of falling after a fall, with resulting activity avoidance and deconditioning, is a recognised post-fall syndrome that itself increases future falls risk through progressive weakness and reduced confidence. The most effective evidence-based intervention is referral to a structured, individualised strength and balance exercise programme (such as the Otago exercise programme), which has been shown to reduce both falls risk and fear of falling by improving physical function and confidence.', 4),
('d5000000-0000-0000-0000-000000000026', 'E', 'Reassure her that fear of falling after a minor injury is not a clinically significant issue', false, 'Ruled out because fear of falling with resultant activity restriction is a well-recognised clinical syndrome associated with increased future falls, functional decline and reduced quality of life, and warrants active intervention rather than reassurance alone.', 5),
('d5000000-0000-0000-0000-000000000027', 'A', $x$Start fludrocortisone immediately without adjusting his Parkinson's medication$x$, false, 'Ruled out because the more appropriate first step, given a clear temporal link to a dopamine agonist dose increase, is to address the likely causative medication and try non-pharmacological measures before adding a specific pharmacological treatment for orthostatic hypotension, which carries its own risks (fluid retention, hypokalaemia, supine hypertension).', 1),
('d5000000-0000-0000-0000-000000000027', 'B', 'Review and consider reducing the dopamine agonist dose, alongside non-pharmacological measures for orthostatic hypotension', true, $x$Correct. Dopamine agonists commonly cause or worsen orthostatic hypotension, and a temporal relationship with a recent dose increase makes this the most likely contributor to his new falls. The most appropriate initial step is to review his Parkinson's medication, considering whether the dopamine agonist dose can be reduced or the regimen adjusted (e.g., increasing levodopa proportionally while reducing agonist dose) while implementing non-pharmacological measures (adequate hydration, slow postural changes, compression garments), reserving specific pharmacological treatment for orthostatic hypotension (such as midodrine or fludrocortisone) for cases where these measures are insufficient.$x$, 2),
('d5000000-0000-0000-0000-000000000027', 'C', 'Increase the dopamine agonist dose further to improve his mobility and reduce falls from motor symptoms', false, 'Ruled out because further increasing a drug that is very likely contributing to his orthostatic hypotension and falls would be expected to worsen his symptomatic postural drop and falls risk, despite any modest additional motor benefit.', 3),
('d5000000-0000-0000-0000-000000000027', 'D', $x$Stop all Parkinson's medications abruptly$x$, false, $x$Ruled out because abrupt cessation of dopaminergic therapy in Parkinson's disease risks acute akinesia and, rarely, a parkinsonism-hyperpyrexia syndrome; medication changes should be considered and adjusted gradually and carefully, not stopped abruptly altogether.$x$, 4),
('d5000000-0000-0000-0000-000000000027', 'E', 'Refer for permanent pacemaker insertion given his falls', false, $x$Ruled out because there is no evidence here of a cardiac conduction abnormality or bradyarrhythmia; his falls are explained by orthostatic hypotension related to his Parkinson's medication, which is a pharmacological rather than a cardiac electrical problem.$x$, 5),
('d5000000-0000-0000-0000-000000000028', 'A', 'Continue anticoagulation, since falls risk alone rarely outweighs the stroke prevention benefit in this context, with ongoing individualised review', true, 'Correct. Decision analyses have shown that a patient would need to fall extremely frequently (historically estimated at several hundred times per year) for the bleeding risk from a fall to outweigh the stroke prevention benefit of anticoagulation in atrial fibrillation with a significant CHA2DS2-VASc score. In the absence of a prior intracranial haemorrhage or other high bleeding risk features, falls risk alone, even with several falls per year without significant injury, is not usually sufficient justification to withhold anticoagulation; ongoing individualised review of falls causes and bleeding risk factors should continue.', 1),
('d5000000-0000-0000-0000-000000000028', 'B', 'Stop anticoagulation immediately because of her falls history', false, 'Ruled out because falls risk alone, without a history of significant bleeding or intracranial haemorrhage, is rarely sufficient reason to stop anticoagulation given the substantial stroke risk reduction it provides in atrial fibrillation with a high CHA2DS2-VASc score; this would expose her to a disproportionately increased stroke risk relative to a modest theoretical bleeding risk from falls.', 2),
('d5000000-0000-0000-0000-000000000028', 'C', 'Switch to aspirin monotherapy as a safer alternative to anticoagulation', false, 'Ruled out because aspirin is not an effective or recommended alternative to anticoagulation for stroke prevention in atrial fibrillation, offering substantially inferior stroke risk reduction while still carrying bleeding risk, and current guidance does not support its use as a fall-risk mitigation strategy in this context.', 3),
('d5000000-0000-0000-0000-000000000028', 'D', 'Continue warfarin unchanged and take no further action regarding her falls', false, 'Ruled out because although anticoagulation should generally continue, this does not mean her falls should be ignored; the underlying causes of her recurrent falls should still be actively investigated and addressed through a falls assessment, independent of the anticoagulation decision.', 4),
('d5000000-0000-0000-0000-000000000028', 'E', 'Refer for left atrial appendage occlusion as a routine alternative for all patients who fall', false, 'Ruled out because left atrial appendage occlusion is generally reserved for patients in whom long-term anticoagulation is contraindicated or not tolerated (e.g., due to major bleeding), not offered routinely as an alternative purely because of falls risk when anticoagulation itself remains appropriate and tolerated.', 5),
('d5000000-0000-0000-0000-000000000029', 'A', 'Increase the gliclazide dose to achieve tighter glycaemic control', false, 'Ruled out because increasing a sulfonylurea dose in a patient already experiencing recurrent symptomatic hypoglycaemia would worsen, not improve, his falls risk, and tighter control is not appropriate given his frailty and cognitive impairment.', 1),
('d5000000-0000-0000-0000-000000000029', 'B', 'Switch to insulin therapy for more precise glucose control', false, 'Ruled out because insulin carries at least as high, if not higher, a hypoglycaemia risk as sulfonylureas, and would not be an appropriate next step when the priority is reducing hypoglycaemia risk and relaxing glycaemic targets in a frail older patient, rather than intensifying treatment.', 2),
('d5000000-0000-0000-0000-000000000029', 'C', 'Continue gliclazide unchanged, as his HbA1c indicates good control that should be maintained', false, 'Ruled out because his HbA1c reflects overly tight control given his frailty and cognitive impairment, and is being achieved at the cost of recurrent dangerous hypoglycaemia causing falls; the correct response is to relax the target and adjust treatment, not maintain the status quo.', 3),
('d5000000-0000-0000-0000-000000000029', 'D', 'Refer for continuous subcutaneous insulin infusion (insulin pump) therapy', false, 'Ruled out because insulin pump therapy is not appropriate or indicated in this context; the priority is to de-intensify treatment and relax glycaemic targets to reduce hypoglycaemia risk, not to introduce a more complex insulin delivery system in a frail, cognitively impaired older patient.', 4),
('d5000000-0000-0000-0000-000000000029', 'E', 'Stop or reduce gliclazide and relax his glycaemic target given his frailty', true, 'Correct. His falls are explained by recurrent symptomatic hypoglycaemia due to gliclazide, a sulfonylurea with a well-recognised risk of hypoglycaemia, particularly in older frail patients whose renal function and food intake may be less predictable. His HbA1c is already tightly controlled (48 mmol/mol), which is inappropriately intensive for someone with frailty and cognitive impairment, where a relaxed target (typically around 58-64 mmol/mol or higher, individualised) is recommended to reduce hypoglycaemia risk; the sulfonylurea should be stopped or reduced, with consideration of a lower hypoglycaemia-risk alternative if glucose-lowering treatment remains needed.', 5),
('d5000000-0000-0000-0000-000000000030', 'A', 'The presence of eight regular medications alone', false, 'Ruled out because polypharmacy, while common in frail patients and a risk factor for adverse outcomes, is not itself a diagnostic criterion for the frailty phenotype and does not by itself establish a diagnosis of frailty.', 1),
('d5000000-0000-0000-0000-000000000030', 'B', 'The number of chronic diagnoses alone, regardless of functional measures', false, 'Ruled out because comorbidity (multiple coexisting diagnoses) is a related but distinct concept from frailty; frailty specifically reflects reduced physiological reserve and vulnerability to stressors, captured through functional measures such as gait speed, grip strength, weight loss and exhaustion, not simply a count of diagnoses.', 2),
('d5000000-0000-0000-0000-000000000030', 'C', 'Meeting three or more of the five Fried frailty phenotype criteria: unintentional weight loss, exhaustion, weakness, slow gait speed, and low physical activity', true, 'Correct. She meets all five components of the Fried frailty phenotype (unintentional weight loss, self-reported exhaustion, weakness on grip strength testing, slow gait speed, and low physical activity), and meeting three or more of these defines frailty as a distinct clinical syndrome of reduced physiological reserve, distinguishable from simple comorbidity (the presence of multiple diagnoses) or disability (dependency in activities of daily living), although the three often coexist and interact.', 3),
('d5000000-0000-0000-0000-000000000030', 'D', 'Her recent increase in hospital admissions alone', false, 'Ruled out because while frailty is associated with increased healthcare utilisation, admission frequency alone is a non-specific marker and not a diagnostic criterion for frailty; it may reflect frailty, disability, comorbidity, or unrelated factors, and does not substitute for a structured frailty assessment.', 4),
('d5000000-0000-0000-0000-000000000030', 'E', 'Her age alone, being over 85 years old', false, 'Ruled out because chronological age alone is a poor predictor of frailty status; some very old patients are robust while some younger older adults are frail, and a structured assessment of physical performance and phenotype criteria is required rather than relying on age.', 5),
('d5000000-0000-0000-0000-000000000031', 'A', 'Continue alendronic acid indefinitely without any reassessment, as osteoporosis treatment should never be stopped', false, 'Ruled out because current guidance explicitly supports reassessment of ongoing bisphosphonate treatment need after 5 years (oral) or 3 years (intravenous), with consideration of a treatment holiday in lower-risk patients, rather than indefinite continuation regardless of risk profile.', 1),
('d5000000-0000-0000-0000-000000000031', 'B', 'Stop alendronic acid permanently, as five years of treatment is sufficient for life', false, 'Ruled out because a treatment holiday is not the same as permanent discontinuation; ongoing risk should be periodically reassessed, and treatment may need to be restarted if there is evidence of declining bone density, a new fracture, or emergence of higher risk features during the holiday.', 2),
('d5000000-0000-0000-0000-000000000031', 'C', 'Switch immediately to denosumab without reassessing her fracture risk', false, 'Ruled out because switching to a different agent is not automatically indicated after a fixed duration of bisphosphonate therapy without first reassessing whether her current risk profile still requires ongoing pharmacological treatment at all; furthermore, switching from a bisphosphonate to denosumab requires careful planning given the risk of rebound bone loss if denosumab is later stopped.', 3),
('d5000000-0000-0000-0000-000000000031', 'D', 'Reassess her fracture risk (repeat DXA and clinical risk factors) and consider a bisphosphonate treatment holiday given her stable, improved bone density and absence of further fractures', true, 'Correct. After five years of oral bisphosphonate therapy, current guidance recommends reassessing fracture risk using DXA and clinical risk factors (such as FRAX). In patients who are not at high ongoing risk (no new fractures, T-score better than around -2.5, no high-risk features such as ongoing glucocorticoid use), a bisphosphonate treatment holiday of typically 2-3 years can be considered, given the prolonged skeletal retention and residual anti-fracture effect of bisphosphonates, and to reduce cumulative risk of atypical femoral fracture and osteonecrosis of the jaw with continued long-term use, with periodic reassessment during the holiday.', 4),
('d5000000-0000-0000-0000-000000000031', 'E', 'Add teriparatide to alendronic acid for combination therapy', false, 'Ruled out because there is no indication here for treatment escalation to anabolic combination therapy; she has had no new fractures and stable/improved bone density, and combining teriparatide with a bisphosphonate is not standard practice and is not indicated for someone potentially eligible for a treatment holiday rather than escalation.', 5),
('d5000000-0000-0000-0000-000000000032', 'A', 'Stop the bisphosphonate and consider anabolic therapy such as teriparatide to promote fracture healing', true, $x$Correct. This presentation (prodromal thigh pain, transverse fracture pattern with lateral cortical thickening/'beaking', minimal trauma, prolonged bisphosphonate exposure) is characteristic of an atypical femoral fracture, a rare but recognised complication of long-term bisphosphonate therapy related to oversuppression of bone remodelling. Management involves stopping the bisphosphonate, ensuring adequate calcium and vitamin D, orthopaedic assessment (often requiring surgical fixation), and consideration of anabolic therapy such as teriparatide, which may promote healing of the fracture and of the contralateral femur, which should also be imaged given the bilateral tendency of this condition.$x$, 1),
('d5000000-0000-0000-0000-000000000032', 'B', 'Continue alendronic acid, as it will help the fracture heal by promoting bone formation', false, 'Ruled out because bisphosphonates suppress bone turnover and are implicated in the pathogenesis of atypical femoral fractures through prolonged remodelling suppression; continuing the drug would not aid healing and could worsen the underlying problem, so it should be stopped.', 2),
('d5000000-0000-0000-0000-000000000032', 'C', 'Switch to denosumab immediately to maintain antiresorptive treatment', false, 'Ruled out because denosumab is also a potent antiresorptive that suppresses bone remodelling, and switching to another antiresorptive agent immediately after an atypical fracture does not address the likely mechanism (oversuppressed remodelling) or support fracture healing; an anabolic approach is preferred in this context.', 3),
('d5000000-0000-0000-0000-000000000032', 'D', 'Manage conservatively with analgesia alone, as this represents a typical osteoporotic fragility fracture', false, 'Ruled out because this is not a typical fragility fracture; the clinical and radiological features (prodromal pain, transverse fracture with cortical beaking, minimal trauma, long bisphosphonate exposure) are specific for atypical femoral fracture, which requires specific recognition, bisphosphonate cessation, and usually surgical fixation given the risk of complete fracture and poor healing potential.', 4),
('d5000000-0000-0000-0000-000000000032', 'E', 'Reassure her that this is unrelated to her bisphosphonate treatment and no medication change is needed', false, 'Ruled out because the clinical and radiographic picture strongly suggests a bisphosphonate-associated atypical femoral fracture, a recognised complication requiring the bisphosphonate to be stopped as part of management.', 5),
('d5000000-0000-0000-0000-000000000033', 'A', 'Stop alendronic acid for at least three months before and after the extraction', false, 'Ruled out because interrupting oral bisphosphonate therapy for a routine dental extraction is not supported by current guidance given the very low MRONJ risk at osteoporosis doses, and unnecessarily stopping treatment exposes her to increased fracture risk without meaningfully reducing an already low MRONJ risk.', 1),
('d5000000-0000-0000-0000-000000000033', 'B', 'Continue alendronic acid; the risk of osteonecrosis of the jaw with oral bisphosphonate use for osteoporosis is very low and does not warrant stopping treatment for a routine extraction', true, 'Correct. The risk of medication-related osteonecrosis of the jaw (MRONJ) with oral bisphosphonates used at osteoporosis doses is very low (substantially lower than with high-dose intravenous bisphosphonates used in oncology), and current dental and osteoporosis guidance does not recommend interrupting oral bisphosphonate therapy for routine dental procedures such as a simple extraction in a patient without additional risk factors. Good oral hygiene and standard dental precautions are appropriate, but osteoporosis treatment should be continued.', 2),
('d5000000-0000-0000-0000-000000000033', 'C', 'Switch to intravenous zoledronic acid before the procedure to reduce osteonecrosis risk', false, 'Ruled out because intravenous bisphosphonates, particularly at oncology doses, carry a higher (though still relatively low at osteoporosis dosing) risk of MRONJ than oral agents, so switching to an intravenous agent would not reduce her risk and is not an appropriate step before a routine dental extraction.', 3),
('d5000000-0000-0000-0000-000000000033', 'D', 'Avoid all future dental extractions permanently while on any bisphosphonate', false, 'Ruled out because necessary dental treatment, including extractions, should not be permanently avoided; the low MRONJ risk with oral bisphosphonates at osteoporosis doses means routine dental care can and should proceed with standard precautions.', 4),
('d5000000-0000-0000-0000-000000000033', 'E', 'Refer for prophylactic antibiotics for two weeks before the extraction to prevent osteonecrosis', false, 'Ruled out because there is no established role for prophylactic long-course antibiotics specifically to prevent MRONJ before a routine extraction in a low-risk patient on oral bisphosphonate therapy; management should follow standard dental care pathways.', 5),
('d5000000-0000-0000-0000-000000000034', 'A', 'Oral alendronic acid alone as first-line treatment, with no plan for anabolic therapy', false, 'Ruled out because in patients at very high fracture risk, an antiresorptive-only approach is less effective at reducing fracture risk than an anabolic-first strategy; oral bisphosphonate monotherapy would not be the optimal initial choice in this very high-risk scenario.', 1),
('d5000000-0000-0000-0000-000000000034', 'B', 'Calcium and vitamin D supplementation alone, deferring specific antiresorptive or anabolic therapy', false, 'Ruled out because calcium and vitamin D supplementation alone is inadequate for a patient at very high fracture risk with a recent hip fracture and multiple vertebral fractures; while ensuring adequate calcium and vitamin D status is important, specific pharmacological treatment (anabolic-first) is required.', 2),
('d5000000-0000-0000-0000-000000000034', 'C', 'An anabolic agent (such as teriparatide or romosozumab) as first-line treatment, followed by an antiresorptive agent to maintain bone density gains', true, $x$Correct. She has very high fracture risk (recent hip fracture, multiple prior vertebral fractures, markedly low T-score) with no prior treatment. Current guidance supports an 'anabolic-first' strategy in patients at very high fracture risk, using an anabolic agent such as teriparatide or romosozumab to rapidly increase bone formation and reduce fracture risk more effectively than starting with an antiresorptive alone, followed by sequential therapy with an antiresorptive agent (such as a bisphosphonate or denosumab) to consolidate and maintain the bone density gains achieved.$x$, 3),
('d5000000-0000-0000-0000-000000000034', 'D', 'Denosumab as first-line monotherapy without any anabolic treatment', false, 'Ruled out because although denosumab is an effective antiresorptive, in patients at very high fracture risk an anabolic-first approach provides superior fracture risk reduction, and starting with an antiresorptive alone (without a planned anabolic phase) is not the optimal strategy here.', 4),
('d5000000-0000-0000-0000-000000000034', 'E', 'No pharmacological treatment, as fracture has already occurred and further treatment will not reduce future risk', false, 'Ruled out because pharmacological treatment substantially reduces the risk of further fractures even after a fragility fracture has occurred, and withholding treatment in this very high-risk patient would leave her at ongoing, largely preventable risk of further fractures.', 5),
('d5000000-0000-0000-0000-000000000035', 'A', 'Reassure her that a delay in denosumab dosing carries no particular risk and treatment can be resumed whenever convenient', false, 'Ruled out because delayed dosing of denosumab is specifically associated with rebound bone turnover and an increased risk of vertebral fractures, so timely action (reinitiating denosumab promptly or bridging with a bisphosphonate) is important rather than an unhurried approach.', 1),
('d5000000-0000-0000-0000-000000000035', 'B', 'Switch to teriparatide immediately as a direct replacement without any bisphosphonate bridging', false, 'Ruled out because starting an anabolic agent alone after denosumab discontinuation does not adequately prevent the rebound increase in bone turnover associated with stopping denosumab, and in fact anabolic monotherapy directly after denosumab cessation may be less effective at preserving bone density than using a bisphosphonate to bridge the transition.', 2),
('d5000000-0000-0000-0000-000000000035', 'C', 'Simply stop all osteoporosis treatment now that she has had a course of denosumab', false, 'Ruled out because stopping denosumab without any follow-on antiresorptive treatment (typically a bisphosphonate) leaves her at significant risk of rebound vertebral fractures; treatment cannot simply be abandoned after a missed dose without a planned strategy to prevent rebound.', 3),
('d5000000-0000-0000-0000-000000000035', 'D', 'Monitor with DXA alone every two years with no treatment change in the interim', false, 'Ruled out because the rebound fracture risk after delayed/discontinued denosumab can manifest within months, well before a two-yearly DXA would detect a problem; active management (reinitiating denosumab or bridging with a bisphosphonate) is needed promptly rather than a purely observational approach.', 4),
('d5000000-0000-0000-0000-000000000035', 'E', 'Arrange prompt reinitiation of denosumab, or if denosumab is to be stopped, give a bisphosphonate to prevent rebound bone loss and vertebral fractures', true, $x$Correct. Delayed or discontinued denosumab dosing is associated with a rebound increase in bone turnover and a recognised risk of multiple, sometimes clustered, vertebral fractures within months of the missed or final dose, related to loss of denosumab's effect without any residual skeletal retention (unlike bisphosphonates). The priority is to either promptly reinitiate denosumab as close to schedule as possible, or, if it is being discontinued, to give a bisphosphonate around the time of the next due dose to prevent rebound bone turnover and reduce vertebral fracture risk.$x$, 5),
('d5000000-0000-0000-0000-000000000036', 'A', 'Start denosumab immediately without correcting her vitamin D level, since denosumab is safe in renal impairment', false, 'Ruled out because although denosumab does not require renal dose adjustment in the way bisphosphonates do, it can still cause significant hypocalcaemia, and this risk is markedly increased in patients with vitamin D deficiency and renal impairment; vitamin D and calcium status should be corrected first regardless of which antiresorptive agent is planned.', 1),
('d5000000-0000-0000-0000-000000000036', 'B', 'Correct her vitamin D deficiency and ensure adequate calcium intake before starting antiresorptive therapy', true, 'Correct. Both bisphosphonates and denosumab can cause significant, sometimes severe and symptomatic, hypocalcaemia, particularly in patients with vitamin D deficiency and renal impairment, where the risk is substantially increased. Vitamin D deficiency and inadequate calcium status should be corrected before starting antiresorptive treatment to reduce this risk, with ongoing monitoring of calcium levels, especially important given her reduced renal function which further impairs calcium homeostasis.', 2),
('d5000000-0000-0000-0000-000000000036', 'C', 'Start oral alendronic acid immediately, as it is safe regardless of renal function or vitamin D status', false, 'Ruled out because oral bisphosphonates are generally avoided or used with caution at significantly reduced eGFR, and starting any antiresorptive agent without correcting vitamin D deficiency risks precipitating hypocalcaemia.', 3),
('d5000000-0000-0000-0000-000000000036', 'D', 'Proceed directly to treatment, as her calcium is within the normal range', false, 'Ruled out because although her corrected calcium is currently low-normal, the combination of vitamin D deficiency and renal impairment predisposes her to significant hypocalcaemia once antiresorptive therapy (which further suppresses bone turnover and calcium release) is started; her current calcium level does not exclude this risk, and vitamin D should be corrected proactively first.', 4),
('d5000000-0000-0000-0000-000000000036', 'E', 'Delay all osteoporosis treatment indefinitely because of her renal impairment', false, 'Ruled out because renal impairment does not preclude osteoporosis treatment altogether; rather, it requires appropriate agent selection (with caution around bisphosphonate use at low eGFR) and correction of vitamin D/calcium status before treatment, not indefinite deferral of any treatment.', 5),
('d5000000-0000-0000-0000-000000000037', 'A', 'Wait for a DXA scan before making any decision about bone protection', false, 'Ruled out because guidance explicitly supports initiating bone-protective treatment in high-risk patients on the basis of clinical risk assessment and glucocorticoid dose without waiting for DXA, given the rapid and early bone loss that occurs after starting glucocorticoids and potential delays in arranging DXA.', 1),
('d5000000-0000-0000-0000-000000000037', 'B', 'Reassure her that bone protection is unnecessary since she has never had a previous fracture', false, 'Ruled out because absence of a prior fragility fracture does not exclude high future fracture risk in the context of anticipated long-term moderate-to-high dose glucocorticoid therapy; her FRAX assessment already identifies her as high risk, meriting treatment regardless of fracture history.', 2),
('d5000000-0000-0000-0000-000000000037', 'C', 'Start bone-protective treatment (e.g., a bisphosphonate) based on her high FRAX-calculated risk without waiting for a DXA scan result', true, 'Correct. In patients starting long-term (expected duration greater than 3 months) moderate-to-high dose glucocorticoid therapy, bone protection decisions should be guided by an algorithm incorporating clinical risk factors and glucocorticoid dose (such as FRAX adjusted for glucocorticoid use, or a dedicated glucocorticoid-induced osteoporosis tool), and treatment can and should be started in high-risk patients without waiting for DXA results, since the fracture risk from prolonged high-dose glucocorticoids is substantial and DXA may take time to arrange, risking a treatment delay in exactly the window when bone loss is most rapid.', 3),
('d5000000-0000-0000-0000-000000000037', 'D', 'Reduce the prednisolone dose rather than starting bone protection, to avoid the need for additional medication', false, 'Ruled out because her prednisolone dose and duration are determined by the underlying need to control her polymyalgia rheumatica, not by a desire to avoid starting bone protection; inappropriately under-dosing glucocorticoid treatment risks inadequate disease control, and bone protection should be added rather than compromising her PMR treatment.', 4),
('d5000000-0000-0000-0000-000000000037', 'E', 'Start calcium and vitamin D supplementation alone, without a bisphosphonate or other specific antiresorptive agent', false, 'Ruled out because calcium and vitamin D supplementation alone is insufficient bone protection for a patient identified as high risk on FRAX in the context of long-term moderate-to-high dose glucocorticoid therapy; specific antiresorptive therapy (typically a bisphosphonate) is indicated in addition to ensuring adequate calcium and vitamin D status.', 5),
('d5000000-0000-0000-0000-000000000038', 'A', 'Intravenous zoledronic acid, administered as an annual infusion', true, 'Correct. Oral bisphosphonates are contraindicated or poorly tolerated in patients with significant oesophageal pathology such as strictures, due to the risk of oesophageal irritation, ulceration or worsening of the underlying condition, and difficulty swallowing tablets appropriately. Intravenous zoledronic acid, given as an annual infusion, bypasses the oesophagus entirely and is an appropriate and effective alternative in this situation, avoiding the gastrointestinal tolerability issues of oral agents.', 1),
('d5000000-0000-0000-0000-000000000038', 'B', 'Switch to a different oral bisphosphonate such as risedronate, which is better tolerated', false, 'Ruled out because although different oral bisphosphonates have slightly different tolerability profiles, all oral bisphosphonates carry a risk of oesophageal irritation and are best avoided in a patient with a known oesophageal stricture and previous severe reflux/swallowing difficulty; an intravenous agent avoiding oesophageal exposure is more appropriate.', 2),
('d5000000-0000-0000-0000-000000000038', 'C', 'Increase the dose of oral alendronic acid to overcome reduced absorption from her stricture', false, 'Ruled out because her problem is tolerability and safety (risk of oesophageal irritation/ulceration) rather than reduced absorption, and increasing the dose of an oral bisphosphonate she cannot tolerate would worsen her symptoms and risk oesophageal injury, not improve treatment.', 3),
('d5000000-0000-0000-0000-000000000038', 'D', 'Discontinue osteoporosis treatment altogether given her intolerance of oral therapy', false, 'Ruled out because effective alternative routes of administration exist (intravenous zoledronic acid, or subcutaneous denosumab), so abandoning osteoporosis treatment entirely is not necessary or appropriate when a suitable alternative can be used.', 4),
('d5000000-0000-0000-0000-000000000038', 'E', 'Crush the alendronic acid tablets and administer via a nasogastric tube', false, 'Ruled out because crushing enteric or specially formulated tablets and administering via a nasogastric tube risks direct oesophageal and gastric mucosal contact with concentrated drug, and does not address the underlying contraindication in a patient with a known oesophageal stricture; this approach is not recommended.', 5),
('d5000000-0000-0000-0000-000000000039', 'A', 'Oral alendronic acid at a standard dose', false, 'Ruled out because oral bisphosphonates are generally not recommended at this level of renal impairment (eGFR 22) due to concerns about drug accumulation and safety in this population, and denosumab is the preferred agent instead.', 1),
('d5000000-0000-0000-0000-000000000039', 'B', 'Intravenous zoledronic acid at a standard dose', false, 'Ruled out because intravenous zoledronic acid is contraindicated at significantly reduced eGFR due to nephrotoxicity risk, and would not be an appropriate choice at this level of renal function; denosumab is preferred as it is not renally cleared.', 2),
('d5000000-0000-0000-0000-000000000039', 'C', 'No pharmacological treatment, given the complexity of her renal function', false, 'Ruled out because effective and appropriate treatment (denosumab, with appropriate monitoring) is available for osteoporosis in advanced chronic kidney disease, and withholding all treatment would leave her at ongoing significant fracture risk unnecessarily.', 3),
('d5000000-0000-0000-0000-000000000039', 'D', 'Denosumab, with close monitoring of calcium levels after initiation', true, 'Correct. Bisphosphonates are renally cleared and are generally avoided or require significant caution at markedly reduced eGFR (commonly below 30-35 ml/min/1.73m2), due to concerns about accumulation and nephrotoxicity, particularly with intravenous agents. Denosumab is not renally cleared and can be used in advanced chronic kidney disease, but carries an increased risk of hypocalcaemia in this population (related to secondary hyperparathyroidism and reduced ability to mobilise calcium), meaning calcium levels should be corrected before treatment (as has been done here) and monitored closely, particularly in the weeks following each injection.', 4),
('d5000000-0000-0000-0000-000000000039', 'E', 'Teriparatide as first-line monotherapy without considering her renal function further', false, 'Ruled out because although teriparatide can be used with some caution in renal impairment, it is not the standard first-line choice here compared with denosumab in a patient without a very high-risk fracture profile requiring an anabolic-first approach, and renal function and calcium/PTH physiology still need careful consideration with any osteoporosis therapy in this context.', 5),
('d5000000-0000-0000-0000-000000000040', 'A', 'Start a bisphosphonate alone, without referral for parathyroid surgery', false, 'Ruled out because although bisphosphonates can be used to manage bone loss in primary hyperparathyroidism when surgery is not possible or declined, in a patient with confirmed disease, evidence of skeletal end-organ damage (fragility fracture), and a localised adenoma amenable to surgery, parathyroidectomy is the definitive treatment of choice and should be offered rather than treating the bone disease pharmacologically alone while leaving the underlying hyperparathyroidism untreated.', 1),
('d5000000-0000-0000-0000-000000000040', 'B', 'Start cinacalcet as first-line management instead of surgical referral', false, 'Ruled out because cinacalcet (a calcimimetic) is generally reserved for patients with primary hyperparathyroidism who are not candidates for surgery, rather than being offered as a first-line alternative to parathyroidectomy in a patient who meets surgical criteria and has a clearly localised, resectable adenoma.', 2),
('d5000000-0000-0000-0000-000000000040', 'C', 'Manage with high fluid intake and observation alone, since her renal function is currently normal', false, 'Ruled out because she has evidence of skeletal end-organ damage from her hyperparathyroidism (osteoporosis with fragility vertebral fractures), which is itself an indication for surgical treatment regardless of renal function or stone disease status; conservative observation is not appropriate given this evidence of harm.', 3),
('d5000000-0000-0000-0000-000000000040', 'D', 'Start denosumab as the definitive treatment for her bone disease', false, 'Ruled out because denosumab treats a consequence (bone loss) of her underlying condition rather than the cause; with a clearly identified, surgically resectable parathyroid adenoma and evidence of skeletal damage, parathyroidectomy is the definitive and preferred treatment rather than long-term antiresorptive therapy alone.', 4),
('d5000000-0000-0000-0000-000000000040', 'E', 'Referral for parathyroidectomy as the definitive treatment', true, 'Correct. This patient has primary hyperparathyroidism (raised calcium with markedly elevated PTH and a confirmed solitary adenoma) causing secondary bone loss and fragility vertebral fractures. Since she has evidence of end-organ damage (osteoporosis with fragility fracture), she meets recognised criteria for surgical intervention, and parathyroidectomy is the definitive treatment, addressing the underlying cause of her bone loss rather than merely treating its consequence with osteoporosis medication alone.', 5),
('d5000000-0000-0000-0000-000000000041', 'A', 'Continue all three medications, and simply increase his fluid intake', false, 'Ruled out because continuing the causative combination of drugs while the patient has significant acute kidney injury and hyperkalaemia risks further deterioration; the NSAID should be stopped as the priority step, not merely counterbalanced with increased fluid intake.', 1),
('d5000000-0000-0000-0000-000000000041', 'B', 'Stop the ramipril only, and continue the NSAID and diuretic', false, 'Ruled out because while ramipril may also need review, the NSAID is a key reversible precipitant of this AKI and should be stopped; simply stopping the ACE inhibitor while continuing regular NSAID use would still expose him to the harmful renal haemodynamic effects of the NSAID.', 2),
('d5000000-0000-0000-0000-000000000041', 'C', 'Increase the ramipril dose to provide better renal protection', false, 'Ruled out because increasing an ACE inhibitor dose in the context of acute kidney injury and hyperkalaemia would worsen, not improve, both his renal function and potassium level; this is the opposite of the appropriate action.', 3),
('d5000000-0000-0000-0000-000000000041', 'D', 'Start an NSAID-sparing analgesic alternative such as a higher dose of the same NSAID with gastroprotection', false, 'Ruled out because gastroprotection addresses gastrointestinal risk, not the renal haemodynamic mechanism responsible for this acute kidney injury, and increasing rather than stopping the NSAID would worsen his renal function further.', 4),
('d5000000-0000-0000-0000-000000000041', 'E', 'Stop the ibuprofen immediately, alongside supportive management of his acute kidney injury', true, $x$Correct. This is the classic 'triple whammy' combination of an ACE inhibitor, a diuretic, and an NSAID, which together substantially increase the risk of acute kidney injury through combined effects on renal perfusion and glomerular filtration (afferent arteriolar vasoconstriction from NSAID-mediated prostaglandin inhibition, combined with ACE inhibitor-related efferent arteriolar vasodilation and diuretic-related volume depletion). The NSAID, as the most recently introduced and most easily discontinued agent, should be stopped immediately as the priority step, alongside supportive management of the AKI and hyperkalaemia and review of his other renally-acting medications.$x$, 5),
('d5000000-0000-0000-0000-000000000042', 'A', 'Focus only on the amitriptyline, as this is the only medication with a known anticholinergic burden score', false, 'Ruled out because oxybutynin, cyclizine, and chlorphenamine, in addition to amitriptyline, all contribute meaningfully to anticholinergic burden, and a comprehensive review considering the cumulative effect of all four agents is required, not a focus on a single drug in isolation.', 1),
('d5000000-0000-0000-0000-000000000042', 'B', 'Systematically review each anticholinergic medication, substituting or stopping agents where possible to reduce her cumulative anticholinergic burden', true, 'Correct. Multiple medications with individually modest anticholinergic activity can combine to produce a significant cumulative anticholinergic burden, which is associated with worsening cognition, confusion, and falls in older people, as seen here. The appropriate approach is a systematic review of each anticholinergic agent, considering whether it remains necessary, and substituting for lower-burden alternatives where possible (for example, mirabegron instead of oxybutynin, a non-anticholinergic analgesic approach for her neuropathic pain, and avoiding chlorphenamine and cyclizine where alternatives exist), rather than treating each medication in isolation without considering their combined effect.', 2),
('d5000000-0000-0000-0000-000000000042', 'C', 'Add a cholinesterase inhibitor to counteract the anticholinergic effects while continuing all current medications', false, 'Ruled out because adding a cholinesterase inhibitor to counteract ongoing anticholinergic drug exposure treats a downstream consequence rather than removing the reversible cause, and exposes her to two opposing pharmacological effects and further polypharmacy rather than simplifying her regimen.', 3),
('d5000000-0000-0000-0000-000000000042', 'D', 'Make no changes, since each medication was started for a valid clinical indication', false, 'Ruled out because a valid original indication does not mean each medication remains appropriate or safe to continue unmodified, particularly when the cumulative effect (elevated anticholinergic burden, worsening cognition and falls) demonstrates ongoing harm requiring active review.', 4),
('d5000000-0000-0000-0000-000000000042', 'E', 'Refer for urgent MRI brain before considering any medication changes', false, 'Ruled out because the clinical picture (multiple anticholinergic medications, elevated anticholinergic burden score, temporally associated confusion and falls) points strongly to a reversible medication-related cause that should be addressed first through medication review, rather than prioritising neuroimaging before addressing this modifiable factor.', 5),
('d5000000-0000-0000-0000-000000000043', 'A', 'Stop diazepam abruptly given the clear wish of the patient and family', false, 'Ruled out because abrupt cessation after a decade of regular benzodiazepine use carries a significant risk of a withdrawal syndrome, including potentially serious complications such as seizures; even with patient and family agreement to stop, this should be achieved through a gradual, supervised taper rather than abrupt discontinuation.', 1),
('d5000000-0000-0000-0000-000000000043', 'B', 'Switch immediately to a full therapeutic dose of a different sedative such as zopiclone', false, 'Ruled out because substituting one sedative-hypnotic for another at a full dose does not address the goal of reducing his overall sedative burden and falls risk, and does not represent an appropriate deprescribing strategy for long-term benzodiazepine dependence.', 2),
('d5000000-0000-0000-0000-000000000043', 'C', 'A gradual, planned dose reduction over a period of weeks to months, with monitoring for withdrawal symptoms', true, 'Correct. Abrupt discontinuation of long-term benzodiazepine therapy, particularly after ten years of regular use, carries a significant risk of a withdrawal syndrome that can include rebound anxiety, insomnia, agitation, and in severe cases seizures. The appropriate approach is a gradual, individualised dose reduction over a period of weeks to months (sometimes longer), with close monitoring for withdrawal symptoms and adjustment of the taper pace as needed, alongside psychological support for his underlying anxiety.', 3),
('d5000000-0000-0000-0000-000000000043', 'D', 'Continue diazepam unchanged indefinitely, as stopping is too risky at his age', false, 'Ruled out because although a cautious approach is needed, gradual dose reduction with appropriate monitoring is both safe and appropriate, and continuing long-term benzodiazepine therapy unmodified perpetuates ongoing risks of sedation, falls, and cognitive impairment without attempting a safe, planned withdrawal.', 4),
('d5000000-0000-0000-0000-000000000043', 'E', 'Increase the dose temporarily before starting any reduction, to make tapering easier', false, 'Ruled out because there is no rationale or evidence supporting a dose increase prior to tapering; this would simply increase his sedative burden and associated risks without facilitating subsequent withdrawal.', 5),
('d5000000-0000-0000-0000-000000000044', 'A', 'Consider stopping atorvastatin, as its cardiovascular benefit takes years to accrue and is unlikely to be realised or clinically meaningful given her limited prognosis', true, 'Correct. Statins provide cardiovascular risk reduction that accrues over a period of years, and in a patient with a life expectancy measured in months due to advanced, terminal illness, the potential benefit of continuing statin therapy is very unlikely to be realised, while it continues to contribute to pill burden and potential side effects. In this context, discontinuing atorvastatin as part of a goals-of-care-oriented medication review is appropriate and aligns with a shift towards comfort-focused, burden-reducing prescribing, ideally discussed with the patient (where possible) and family.', 1),
('d5000000-0000-0000-0000-000000000044', 'B', 'Continue atorvastatin unchanged, as secondary prevention medications should never be stopped', false, $x$Ruled out because the appropriateness of secondary prevention medications, including statins, should be reconsidered in the context of a patient's overall prognosis and goals of care; in advanced terminal illness with a very limited life expectancy, the long time-to-benefit of statins means continuing treatment is unlikely to provide meaningful benefit and adds unnecessary burden.$x$, 2),
('d5000000-0000-0000-0000-000000000044', 'C', 'Increase the atorvastatin dose to maximise cardiovascular protection', false, 'Ruled out because increasing statin dose intensity is not appropriate when the overarching goal, given her very limited prognosis, is to reduce medication burden and focus on comfort rather than pursuing long-term risk reduction that is very unlikely to be realised.', 3),
('d5000000-0000-0000-0000-000000000044', 'D', 'Switch to a different statin rather than considering discontinuation', false, 'Ruled out because the issue here is not statin choice or tolerability, but rather whether ongoing statin therapy of any kind remains appropriate given her very limited prognosis; switching agents does not address this underlying consideration.', 4),
('d5000000-0000-0000-0000-000000000044', 'E', 'Refer for a full lipid profile to guide further statin dose titration', false, 'Ruled out because further lipid monitoring and dose titration are not a priority, and are arguably inappropriate, in a patient with an advanced, terminal illness and very limited life expectancy where the focus should shift towards deprescribing medications unlikely to provide timely benefit.', 5),
('d5000000-0000-0000-0000-000000000045', 'A', 'This represents a coincidental deterioration in his diet unrelated to the new antibiotic', false, 'Ruled out because the clear temporal relationship between starting clarithromycin, a well-recognised CYP450 inhibitor with a known clinically significant interaction with warfarin, and the development of a markedly supratherapeutic INR with bleeding, strongly implicates a drug interaction rather than a coincidental dietary change.', 1),
('d5000000-0000-0000-0000-000000000045', 'B', 'Increase the warfarin dose to compensate for reduced anticoagulant effect', false, 'Ruled out because his INR is already markedly elevated (supratherapeutic) with active bleeding symptoms, indicating excessive rather than reduced anticoagulant effect; increasing the warfarin dose would be dangerous and is the opposite of the appropriate response.', 2),
('d5000000-0000-0000-0000-000000000045', 'C', 'Continue both warfarin and clarithromycin unchanged, as this INR level is expected to resolve spontaneously without intervention', false, 'Ruled out because a supratherapeutic INR of 8.6 with bleeding symptoms requires active intervention (INR reversal measures as appropriate, and stopping the interacting drugs) rather than passive observation, given the risk of serious bleeding complications.', 3),
('d5000000-0000-0000-0000-000000000045', 'D', 'Clarithromycin has inhibited warfarin metabolism via CYP3A4, causing a supratherapeutic INR; the antibiotic should be stopped or switched, and his anticoagulation managed according to bleeding severity and INR level', true, $x$Correct. Clarithromycin is a potent inhibitor of hepatic cytochrome P450 enzymes (particularly CYP3A4, with some effect on other pathways relevant to warfarin metabolism), significantly increasing warfarin's anticoagulant effect and precipitating this markedly supratherapeutic INR with bleeding symptoms. Management involves stopping or switching the interacting antibiotic to a non-interacting alternative, withholding warfarin, and treating the elevated INR and bleeding according to its severity and current anticoagulation reversal guidance (e.g., vitamin K with or without prothrombin complex concentrate depending on bleeding severity), followed by careful INR monitoring as the interaction resolves.$x$, 4),
('d5000000-0000-0000-0000-000000000045', 'E', 'Switch him from warfarin to aspirin for the remainder of the antibiotic course', false, 'Ruled out because aspirin does not provide equivalent stroke prevention in atrial fibrillation and abruptly switching anticoagulant strategy is not the appropriate response to a drug interaction causing a transient supratherapeutic INR; the interacting antibiotic should be addressed and his anticoagulation managed and monitored appropriately instead.', 5),
('d5000000-0000-0000-0000-000000000046', 'A', 'Continue omeprazole unchanged indefinitely, as long-term use in older people is not associated with significant risk', false, 'Ruled out because long-term PPI use is associated with several recognised risks in older people, including fracture, Clostridioides difficile infection, and micronutrient deficiencies, meaning ongoing use without a clear continuing indication should be reviewed rather than continued indefinitely by default.', 1),
('d5000000-0000-0000-0000-000000000046', 'B', 'Attempt gradual dose reduction and discontinuation of omeprazole, given the absence of an ongoing indication', true, $x$Correct. In the absence of an ongoing indication for maintenance proton pump inhibitor therapy (such as Barrett's oesophagus, continued NSAID use, or severe erosive oesophagitis), long-term PPI use carries recognised risks including increased fracture risk, Clostridioides difficile infection, hypomagnesaemia, vitamin B12 deficiency, and community-acquired pneumonia. A structured, gradual dose reduction and trial of discontinuation is appropriate here, with monitoring for symptom recurrence and a plan to restart at the lowest effective dose if symptoms return.$x$, 2),
('d5000000-0000-0000-0000-000000000046', 'C', 'Increase the omeprazole dose as a precaution against future dyspepsia recurrence', false, 'Ruled out because there is no current indication or symptom burden to justify increasing her dose; escalating an unnecessary medication would increase, not reduce, her exposure to long-term PPI-associated risks.', 3),
('d5000000-0000-0000-0000-000000000046', 'D', 'Stop omeprazole abruptly with no plan for symptom monitoring or the possibility of rebound acid hypersecretion', false, 'Ruled out because although discontinuation is appropriate, abrupt cessation after long-term use can be associated with rebound acid hypersecretion and transient symptom recurrence; a gradual, planned reduction with monitoring for symptoms and a strategy to manage any recurrence is a more appropriate approach than an unplanned abrupt stop.', 4),
('d5000000-0000-0000-0000-000000000046', 'E', 'Switch to a different proton pump inhibitor at an equivalent dose rather than considering discontinuation', false, 'Ruled out because switching between PPIs does not address the underlying issue, which is the absence of an ongoing indication for continued acid suppression; the appropriate step is to attempt discontinuation, not simply substitute one PPI for another.', 5),
('d5000000-0000-0000-0000-000000000047', 'A', 'Withhold further doses of both the opioid and benzodiazepine, monitor closely including respiratory rate and oxygen saturation, and plan a supervised taper rather than abrupt long-term discontinuation of the opioid', true, 'Correct. The combination of a long-acting opioid and a benzodiazepine has an additive, sometimes synergistic, sedative and respiratory depressant effect, and this patient shows signs of clinically significant over-sedation with respiratory depression (reduced respiratory rate, hypoxia, reduced consciousness) and a fall. The immediate priority is to withhold further doses of both drugs and closely monitor his respiratory status, with naloxone available if severe respiratory depression progresses; going forward, his regimen should be rationalised with a supervised, gradual reduction of the benzodiazepine (recently and likely unnecessarily added) and reassessment of his analgesic regimen, rather than abrupt discontinuation of long-term opioid therapy which itself carries withdrawal risk.', 1),
('d5000000-0000-0000-0000-000000000047', 'B', 'Continue both medications at the same doses, as he needs both for pain and anxiety', false, 'Ruled out because he is showing signs of significant over-sedation and respiratory depression from the combination of these two sedating drugs, and continuing both unmodified risks further deterioration, potentially fatal respiratory depression, and further falls.', 2),
('d5000000-0000-0000-0000-000000000047', 'C', 'Increase the lorazepam dose to settle his agitation from apparent opioid withdrawal', false, 'Ruled out because his clinical picture (drowsiness, reduced respiratory rate, hypoxia) indicates over-sedation and respiratory depression from combined opioid-benzodiazepine use, not opioid withdrawal; increasing the benzodiazepine dose would worsen his dangerous over-sedation.', 3),
('d5000000-0000-0000-0000-000000000047', 'D', 'Abruptly stop his long-term modified-release morphine completely with no tapering plan', false, 'Ruled out because although the acute combination needs addressing, abruptly stopping long-term opioid therapy used for chronic pain risks withdrawal symptoms and uncontrolled pain; a safer approach is to withhold doses acutely while he is over-sedated, then reassess and adjust his regimen in a planned, supervised way rather than abrupt permanent cessation.', 4),
('d5000000-0000-0000-0000-000000000047', 'E', 'Add a stimulant medication to counteract the sedation while continuing both drugs unchanged', false, 'Ruled out because using a stimulant to mask dangerous sedation and respiratory depression from an opioid-benzodiazepine combination does not address the underlying cause and risks masking clinical deterioration rather than treating it; the priority is to withhold the causative drugs and monitor closely.', 5),
('d5000000-0000-0000-0000-000000000048', 'A', 'Continue digoxin at the same dose and simply increase furosemide to manage her oedema more aggressively', false, 'Ruled out because continuing digoxin in the context of confirmed toxicity with a significantly elevated level and hypokalaemia would risk worsening arrhythmia, and increasing the diuretic would further worsen her hypokalaemia and toxicity risk.', 1),
('d5000000-0000-0000-0000-000000000048', 'B', 'Increase the digoxin dose to improve rate control given her palpitations', false, 'Ruled out because her palpitations and ventricular ectopy are manifestations of digoxin toxicity itself, not undertreated atrial fibrillation; increasing the dose would worsen her toxicity and arrhythmia risk.', 2),
('d5000000-0000-0000-0000-000000000048', 'C', 'Administer digoxin-specific antibody fragments immediately regardless of clinical severity', false, 'Ruled out because digoxin-specific antibody fragments are generally reserved for severe or life-threatening toxicity (significant arrhythmia, very high digoxin levels with severe symptoms, or hyperkalaemia from acute overdose) rather than used as first-line treatment for all cases of digoxin toxicity; her presentation with ventricular ectopics and mild-moderate toxicity should first be managed with digoxin withholding and potassium correction, reserving antibody fragments for more severe deterioration.', 3),
('d5000000-0000-0000-0000-000000000048', 'D', 'Correct the hypokalaemia rapidly with intravenous potassium boluses without cardiac monitoring', false, 'Ruled out because rapid, unmonitored potassium correction carries its own risk of iatrogenic hyperkalaemia and arrhythmia, particularly in a patient already at risk of cardiac arrhythmia from digoxin toxicity; potassium replacement should be given carefully, typically via controlled intravenous infusion with cardiac monitoring, not rapid bolus dosing.', 4),
('d5000000-0000-0000-0000-000000000048', 'E', 'Withhold digoxin, correct the hypokalaemia, and monitor closely for arrhythmia, reserving digoxin-specific antibody fragments for severe or life-threatening toxicity', true, 'Correct. This is digoxin toxicity precipitated by furosemide-induced hypokalaemia, which increases myocardial sensitivity to digoxin and its arrhythmogenic effects; hypokalaemia also reduces competition with digoxin for the same binding site on the Na+/K+-ATPase pump, further increasing its effect. Immediate management involves withholding digoxin, careful potassium replacement (with cardiac monitoring, as rapid correction has its own risks), and close observation for arrhythmia; digoxin-specific antibody fragments (DigiFab) should be reserved for severe or life-threatening toxicity, such as significant bradyarrhythmia, ventricular tachyarrhythmia, or severe hyperkalaemia from acute massive overdose, rather than used routinely for milder toxicity.', 5),
('d5000000-0000-0000-0000-000000000049', 'A', 'Continue chlorphenamine at the same dose, as it has been well tolerated for years', false, 'Ruled out because the emergence of new confusion, increasing drowsiness and a fall indicates that ongoing use is now causing harm, regardless of how long it has previously been tolerated; this pattern should prompt discontinuation rather than continuation.', 1),
('d5000000-0000-0000-0000-000000000049', 'B', 'Increase the chlorphenamine dose to improve his sleep quality', false, 'Ruled out because increasing the dose of a sedating anticholinergic drug that is already causing confusion and falls would worsen these adverse effects, rather than providing a net benefit.', 2),
('d5000000-0000-0000-0000-000000000049', 'C', 'Add a second sedative medication to help with his insomnia while continuing chlorphenamine', false, 'Ruled out because adding a further sedative to a regimen already causing confusion and falls would compound his sedative and anticholinergic burden and increase his risk of further adverse events, rather than addressing the underlying problem.', 3),
('d5000000-0000-0000-0000-000000000049', 'D', 'Stop chlorphenamine and consider a non-sedating antihistamine or non-pharmacological approach for his symptoms', true, 'Correct. Chlorphenamine is a first-generation antihistamine with substantial anticholinergic and sedative properties, and is identified in explicit prescribing criteria (such as STOPP/Beers criteria) as generally inappropriate for regular use in older people due to the risk of confusion, dry mouth, constipation, urinary retention, and falls, as seen in this patient. It should be stopped, with consideration of a non-sedating, less anticholinergic antihistamine (such as a second-generation agent) if ongoing allergy treatment is needed, and non-pharmacological sleep hygiene measures addressed for his insomnia rather than continuing a sedating antihistamine for this purpose.', 4),
('d5000000-0000-0000-0000-000000000049', 'E', 'Switch to promethazine, another first-generation antihistamine, at an equivalent dose', false, 'Ruled out because promethazine shares similar sedative and anticholinergic properties to chlorphenamine, and switching between two similarly problematic first-generation antihistamines would not address the underlying issue; a genuinely lower-burden alternative (a non-sedating second-generation antihistamine) or a non-pharmacological approach should be used instead.', 5),
('d5000000-0000-0000-0000-000000000050', 'A', 'Increase the furosemide dose further to control his persistent oedema', false, 'Ruled out because amlodipine-induced ankle oedema results from vasodilation rather than fluid overload and responds poorly to diuretics; increasing the furosemide dose would worsen his volume depletion and postural hypotension without effectively treating the oedema, which is a hallmark of a worsening prescribing cascade.', 1),
('d5000000-0000-0000-0000-000000000050', 'B', 'Add a second antihypertensive to allow the amlodipine dose to be reduced without addressing the furosemide', false, 'Ruled out because although reducing amlodipine is appropriate, simply adding another antihypertensive while continuing furosemide unmodified does not address the core issue that the diuretic was inappropriately started to treat a drug side effect and is now itself causing harm (postural hypotension, falls); the furosemide indication should be reassessed as part of unwinding the cascade.', 2),
('d5000000-0000-0000-0000-000000000050', 'C', 'Recognise this as a prescribing cascade; reduce or stop the amlodipine (the original cause of the ankle oedema) rather than continuing the furosemide', true, 'Correct. Amlodipine, a dihydropyridine calcium channel blocker, characteristically causes ankle oedema through precapillary vasodilation, which is not a fluid overload state and therefore does not respond well to diuretics. Adding furosemide to treat amlodipine-induced oedema, without addressing the underlying cause, represents a prescribing cascade, and has now caused a second adverse effect (volume depletion contributing to postural hypotension and a fall). The correct approach is to recognise and unwind this cascade by reducing or stopping the amlodipine (the original causative drug), which should improve the oedema directly, and to reassess the ongoing need for furosemide rather than persisting with a diuretic that is treating a drug side effect ineffectively while causing its own harm.', 3),
('d5000000-0000-0000-0000-000000000050', 'D', 'Continue both amlodipine and furosemide unchanged and refer to a cardiologist for suspected heart failure', false, 'Ruled out because his ankle oedema and subsequent symptoms are explained by a medication-induced prescribing cascade rather than new heart failure; continuing both causative drugs unchanged and pursuing an alternative diagnosis would delay the correct, straightforward management of stopping/reducing the causative drug.', 4),
('d5000000-0000-0000-0000-000000000050', 'E', 'Stop furosemide alone and leave the amlodipine dose unchanged', false, 'Ruled out because although furosemide should be reviewed, simply stopping it while continuing the original causative agent (amlodipine) at an unchanged dose would leave his ankle oedema unresolved, since amlodipine is the actual underlying cause that needs to be addressed.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d5000000-0000-0000-0000-000000000001', $x$Antimuscarinic drugs for overactive bladder (oxybutynin, solifenacin, tolterodine) carry meaningful anticholinergic burden and can precipitate confusion, falls and constipation in older or cognitively vulnerable patients, particularly those with Parkinson's disease or dementia.$x$, 1),
('d5000000-0000-0000-0000-000000000001', 'Mirabegron, a beta-3 adrenoceptor agonist, is an effective alternative for overactive bladder that avoids central anticholinergic effects, though it can raise blood pressure and should be used cautiously in uncontrolled hypertension.', 2),
('d5000000-0000-0000-0000-000000000001', 'When a new symptom (here, confusion) follows starting a drug with a plausible mechanism, the priority is to stop that drug rather than substitute another agent from the same class or add further anticholinergic medication.', 3),
('d5000000-0000-0000-0000-000000000002', 'Chronic urinary retention can present painlessly with overflow incontinence rather than classic retention symptoms, and should be suspected when incontinence coexists with a palpable bladder and rising creatinine.', 1),
('d5000000-0000-0000-0000-000000000002', 'Obstructive uropathy causing acute kidney injury is a post-renal AKI that is typically rapidly reversible once the obstruction is relieved by catheterisation, distinguishing it from intrinsic renal causes.', 2),
('d5000000-0000-0000-0000-000000000002', 'Post-obstructive diuresis after relief of high-pressure retention can cause substantial urine output with sodium, potassium and water losses, requiring monitoring of fluid balance and electrolytes to avoid dehydration or electrolyte derangement.', 3),
('d5000000-0000-0000-0000-000000000003', 'Bacteriuria is near-universal in patients with long-term indwelling catheters; a positive urine dipstick or culture in this context should not prompt antibiotic treatment unless accompanied by systemic or localising symptoms.', 1),
('d5000000-0000-0000-0000-000000000003', 'Diagnosing catheter-associated urinary tract infection requires clinical features (fever, rigors, new confusion, loin or suprapubic pain) in addition to a positive culture, not the culture result in isolation.', 2),
('d5000000-0000-0000-0000-000000000003', 'Overtreatment of asymptomatic bacteriuria is a common and important source of unnecessary antibiotic exposure in care home residents and contributes to the development of resistant organisms.', 3),
('d5000000-0000-0000-0000-000000000004', 'Duloxetine is a recognised second-line option for stress urinary incontinence in women who are not candidates for, or decline, surgical treatment, acting via enhanced urethral sphincter tone rather than detrusor effects.', 1),
('d5000000-0000-0000-0000-000000000004', 'Correctly distinguishing stress incontinence (sphincteric/pelvic floor weakness, leakage on exertion) from urge incontinence (detrusor overactivity) is essential, as antimuscarinics and beta-3 agonists target the latter mechanism and are not effective for pure stress incontinence.', 2),
('d5000000-0000-0000-0000-000000000004', 'Comorbidity-driven unsuitability for surgery should prompt exploration of medical alternatives rather than proceeding with an operation against a considered multidisciplinary risk assessment.', 3),
('d5000000-0000-0000-0000-000000000005', 'Overflow (spurious) diarrhoea occurs when liquid stool bypasses a faecal impaction; it should be actively considered in any older patient reporting new loose stool who also has a history of constipation, especially with a palpable abdominal or rectal mass.', 1),
('d5000000-0000-0000-0000-000000000005', 'Anti-motility agents such as loperamide are contraindicated in overflow diarrhoea from impaction, as they worsen the underlying constipation and impaction.', 2),
('d5000000-0000-0000-0000-000000000005', 'First-line treatment of faecal impaction is a high-dose oral macrogol disimpaction regimen, escalating to stimulant laxatives or rectal measures (suppositories/enema) if oral treatment alone is insufficient.', 3),
('d5000000-0000-0000-0000-000000000006', 'Hospital-associated deconditioning is common in older inpatients and is exacerbated by avoidable factors such as unnecessary catheterisation, prolonged bed rest and reduced opportunities for mobilisation.', 1),
('d5000000-0000-0000-0000-000000000006', 'Comprehensive geriatric assessment is the structured process for identifying and addressing the multiple medical, functional, psychological and social contributors to decline in frail older patients admitted to hospital.', 2),
('d5000000-0000-0000-0000-000000000006', 'New functional impairment after acute illness should not automatically be assumed to represent a fixed new baseline; a trial of active rehabilitation is appropriate before considering long-term care placement.', 3),
('d5000000-0000-0000-0000-000000000007', 'The classic triad of normal pressure hydrocephalus is gait disturbance (typically the earliest and most prominent feature), urinary incontinence, and cognitive impairment, supported by imaging showing ventriculomegaly out of proportion to cortical atrophy.', 1),
('d5000000-0000-0000-0000-000000000007', 'A large-volume (therapeutic) lumbar puncture with objective pre- and post-procedure gait assessment (or extended lumbar drainage in equivocal cases) is used to help predict response to ventriculoperitoneal shunting before committing to surgery.', 2),
('d5000000-0000-0000-0000-000000000007', $x$Normal pressure hydrocephalus is an important reversible cause of gait and cognitive decline in older adults that should be actively considered and distinguished from Alzheimer's disease and Parkinsonian syndromes.$x$, 3),
('d5000000-0000-0000-0000-000000000008', 'Alpha-blockers used for BPH symptoms can cause significant first-dose and sustained postural hypotension, particularly when combined with other antihypertensive drugs, and are an important reversible contributor to falls in older people.', 1),
('d5000000-0000-0000-0000-000000000008', 'A fall with a demonstrated orthostatic blood pressure drop after starting a new drug should prompt withdrawal or dose reduction of the likely causative agent and broader medication review, rather than simply continuing treatment or adding further drugs.', 2),
('d5000000-0000-0000-0000-000000000008', 'Management of medication-induced postural hypotension should prioritise removing or reducing causative drugs before considering pharmacological treatments such as fludrocortisone or midodrine.', 3),
('d5000000-0000-0000-0000-000000000009', 'Evening dosing of diuretics is a frequently overlooked but easily correctable cause of nocturnal polyuria, sleep disturbance and falls in older people, and should be actively sought when reviewing nocturia and unexplained falls.', 1),
('d5000000-0000-0000-0000-000000000009', 'Adjusting diuretic timing to earlier in the day, rather than changing the dose or stopping the drug, preserves therapeutic benefit while reducing night-time urine output.', 2),
('d5000000-0000-0000-0000-000000000009', 'A structured falls history should always include a review of the timing, not just the type, of medications that could contribute to nocturnal symptoms.', 3),
('d5000000-0000-0000-0000-000000000010', 'In mixed urinary incontinence, treatment should target the component that is most bothersome to the individual patient rather than assuming urgency always predominates.', 1),
('d5000000-0000-0000-0000-000000000010', 'Options for stress urinary incontinence (pelvic floor optimisation, duloxetine, surgical referral) are distinct from those for urgency incontinence (antimuscarinics, mirabegron, and later-line botulinum toxin), and selecting the correct pathway requires clarifying which symptom is driving bother.', 2),
('d5000000-0000-0000-0000-000000000010', 'Botulinum toxin bladder injections are reserved for refractory detrusor overactivity after oral pharmacological therapy has failed, not used as an initial treatment.', 3),
('d5000000-0000-0000-0000-000000000011', 'Pharmacological treatment for agitation in delirium should only be considered after non-pharmacological measures have failed and reversible causes have been addressed, and should be reserved for patients at risk of harming themselves or others.', 1),
('d5000000-0000-0000-0000-000000000011', 'Low-dose, short-course haloperidol is generally recommended for severe agitation in delirium in patients without Parkinsonism, Lewy body dementia, or significant QT prolongation, given the risk of severe extrapyramidal reactions in those populations.', 2),
('d5000000-0000-0000-0000-000000000011', 'Benzodiazepines are not first-line for delirium-related agitation outside of alcohol or benzodiazepine withdrawal, or where antipsychotics are contraindicated, as they can paradoxically worsen confusion.', 3),
('d5000000-0000-0000-0000-000000000012', 'Dementia with Lewy bodies carries a substantial risk of severe neuroleptic sensitivity reactions to antipsychotics, particularly typical agents such as haloperidol, which should be avoided wherever possible.', 1),
('d5000000-0000-0000-0000-000000000012', 'When pharmacological treatment cannot be avoided in dementia with Lewy bodies, a low-dose atypical antipsychotic with lower extrapyramidal liability (such as quetiapine) is preferred, started cautiously with close monitoring.', 2),
('d5000000-0000-0000-0000-000000000012', 'Non-pharmacological strategies and treatment of precipitants remain first-line even in this population; drug treatment is reserved for significant distress or risk not otherwise controlled.', 3),
('d5000000-0000-0000-0000-000000000013', 'Cholinesterase inhibitors (donepezil, rivastigmine, galantamine) increase vagal tone and can cause bradycardia, syncope, and atrioventricular conduction block, particularly at higher doses or in patients with pre-existing conduction disease.', 1),
('d5000000-0000-0000-0000-000000000013', 'New bradycardia or conduction abnormality temporally related to starting or increasing a cholinesterase inhibitor should prompt stopping the drug and cardiology assessment, rather than continuing or merely reducing the dose.', 2),
('d5000000-0000-0000-0000-000000000013', 'Cholinesterase inhibitors should be used cautiously, with baseline and follow-up assessment of heart rate, in patients with known cardiac conduction disease or those on other rate-limiting drugs.', 3),
('d5000000-0000-0000-0000-000000000014', $x$Risperidone is the only UK-licensed antipsychotic for short-term (up to 6 weeks) treatment of persistent aggression in Alzheimer's and vascular dementia refractory to non-pharmacological measures.$x$, 1),
('d5000000-0000-0000-0000-000000000014', 'Antipsychotic use in dementia carries an increased risk of stroke and all-cause mortality, meaning treatment should be at the lowest effective dose, for the shortest duration, with regular structured review.', 2),
('d5000000-0000-0000-0000-000000000014', 'Non-pharmacological, person-centred approaches remain first-line for behavioural and psychological symptoms of dementia and should be systematically trialled and reassessed before and alongside any drug treatment.', 3),
('d5000000-0000-0000-0000-000000000015', 'Cumulative anticholinergic burden from multiple drugs, even when each individually seems minor, is a recognised and modifiable contributor to cognitive decline, confusion and falls in older people, particularly those with pre-existing dementia.', 1),
('d5000000-0000-0000-0000-000000000015', 'Structured medication review using an anticholinergic burden framework should identify and prioritise deprescribing or substitution of high-burden agents (e.g., oxybutynin, tricyclic antidepressants, sedating antihistamines) where alternatives exist.', 2),
('d5000000-0000-0000-0000-000000000015', 'New or accelerating cognitive decline in a patient with dementia should always prompt a search for reversible contributors, including medications, before attributing the change solely to disease progression.', 3),
('d5000000-0000-0000-0000-000000000016', 'Postoperative delirium after hip fracture surgery is common and is frequently driven by identifiable, reversible precipitants including urinary retention, constipation, pain, infection, hypoxia and metabolic disturbance, which should be systematically sought and treated first.', 1),
('d5000000-0000-0000-0000-000000000016', 'Urinary retention and faecal impaction are easily overlooked but common and readily treatable contributors to acute confusion in postoperative older patients and should be actively assessed with a bladder scan and abdominal/rectal examination.', 2),
('d5000000-0000-0000-0000-000000000016', 'Pharmacological treatment for agitation in delirium should be reserved until reversible causes have been assessed and non-pharmacological strategies attempted, unless there is an immediate safety crisis.', 3),
('d5000000-0000-0000-0000-000000000017', 'In patients with significant hepatic impairment, benzodiazepines requiring hepatic oxidative metabolism (chlordiazepoxide, diazepam) can accumulate due to active metabolites, whereas lorazepam (metabolised by glucuronidation) is preferred as it avoids this risk.', 1),
('d5000000-0000-0000-0000-000000000017', 'Untreated alcohol withdrawal can progress to seizures and delirium tremens, which carry significant morbidity and mortality, so benzodiazepine treatment (symptom-triggered or fixed-schedule) remains essential even in patients with hepatic impairment, using a safer agent.', 2),
('d5000000-0000-0000-0000-000000000017', $x$Intravenous thiamine should be given to prevent Wernicke's encephalopathy in alcohol withdrawal, but it is an adjunct, not a substitute, for benzodiazepine-based management of the withdrawal syndrome itself.$x$, 3),
('d5000000-0000-0000-0000-000000000018', $x$Frontotemporal dementia is not associated with the same cholinergic deficit as Alzheimer's disease, and cholinesterase inhibitors and memantine lack evidence of benefit and may worsen behaviour in some patients with this condition.$x$, 1),
('d5000000-0000-0000-0000-000000000018', 'SSRIs have better evidence for managing behavioural and psychological symptoms (disinhibition, compulsive behaviours) in frontotemporal dementia compared with cholinesterase inhibitors or memantine.', 2),
('d5000000-0000-0000-0000-000000000018', $x$Distinguishing the underlying dementia subtype is essential for selecting appropriate pharmacotherapy, since drugs effective in Alzheimer's disease are not necessarily effective, and may occasionally be harmful, in other dementias.$x$, 3),
('d5000000-0000-0000-0000-000000000019', 'Delirium can persist for days to weeks after the underlying precipitant has resolved, particularly in patients with pre-existing dementia, and full recovery should not be expected immediately after treating the initial cause.', 1),
('d5000000-0000-0000-0000-000000000019', 'Before adding an antipsychotic for ongoing agitation in delirium, a systematic reassessment for other or persisting reversible contributing factors should always be performed.', 2),
('d5000000-0000-0000-0000-000000000019', 'Antipsychotics in delirium and dementia carry meaningful risks and should be reserved for situations where non-pharmacological measures and correction of underlying causes have failed and there is significant distress or safety risk.', 3),
('d5000000-0000-0000-0000-000000000020', 'Gastrointestinal side effects of oral cholinesterase inhibitors are related to peak plasma concentrations, and switching to a transdermal patch formulation (available for rivastigmine) reduces these peaks and improves tolerability while retaining efficacy.', 1),
('d5000000-0000-0000-0000-000000000020', 'A patient demonstrating clear cognitive benefit from a drug class should, where possible, have tolerability issues addressed through dose or formulation adjustment rather than outright discontinuation of an effective treatment.', 2),
('d5000000-0000-0000-0000-000000000020', 'Adding further medications (such as antiemetics with their own risk profile) to manage a side effect should be weighed against simpler solutions, such as changing the formulation of the causative drug.', 3),
('d5000000-0000-0000-0000-000000000021', 'Medication review to identify and reduce or stop drugs contributing to postural hypotension (antihypertensives, alpha-blockers, diuretics) should be the first step in managing symptomatic orthostatic hypotension in older people, before considering pharmacological treatments aimed at raising blood pressure.', 1),
('d5000000-0000-0000-0000-000000000021', 'A drop of 20 mmHg systolic or 10 mmHg diastolic on standing, especially when reproducing symptoms, defines clinically significant orthostatic hypotension warranting active management.', 2),
('d5000000-0000-0000-0000-000000000021', 'Falls assessment in older people should include lying-standing blood pressure measurement as a routine component, given how commonly orthostatic hypotension contributes to falls.', 3),
('d5000000-0000-0000-0000-000000000022', 'The Clinical Frailty Scale is a validated prognostic tool that correlates with outcomes in acutely unwell older adults, but should inform, rather than solely determine, decisions about escalation of care such as ICU admission.', 1),
('d5000000-0000-0000-0000-000000000022', 'Ceiling of care decisions should be individualised, incorporating frailty assessment, the severity and reversibility of the acute illness, comorbidities, and shared decision-making with the patient and/or family wherever possible.', 2),
('d5000000-0000-0000-0000-000000000022', 'Chronological age alone is a poor surrogate for physiological reserve and should not replace a structured frailty and functional assessment when making treatment escalation decisions.', 3),
('d5000000-0000-0000-0000-000000000023', 'Carotid sinus hypersensitivity is classified into cardioinhibitory (asystolic pause), vasodepressor (blood pressure drop without significant pause), and mixed subtypes, based on carotid sinus massage findings under monitoring.', 1),
('d5000000-0000-0000-0000-000000000023', 'Cardioinhibitory carotid sinus hypersensitivity, particularly with pauses greater than 3 seconds reproducing symptoms, is treated definitively with permanent pacemaker implantation.', 2),
('d5000000-0000-0000-0000-000000000023', 'Vasodepressor and mixed subtypes require different management strategies (such as vasoconstrictor agents or physical counterpressure manoeuvres) since pacing alone does not address a significant blood pressure component.', 3),
('d5000000-0000-0000-0000-000000000024', 'Benign paroxysmal positional vertigo is diagnosed clinically by a positive Dix-Hallpike test showing characteristic transient, fatiguing, torsional-upbeating nystagmus with associated brief vertigo.', 1),
('d5000000-0000-0000-0000-000000000024', 'The Epley manoeuvre is the recommended first-line treatment for posterior canal BPPV, more effective than pharmacological vestibular suppressants, which should not be used regularly.', 2),
('d5000000-0000-0000-0000-000000000024', 'BPPV is an important and treatable contributor to falls risk in older people and should be actively sought and treated as part of a falls assessment when positional vertigo is described.', 3),
('d5000000-0000-0000-0000-000000000025', 'The Fried frailty phenotype is defined by meeting three or more of: unintentional weight loss, self-reported exhaustion, weakness (low grip strength), slow gait speed, and low physical activity.', 1),
('d5000000-0000-0000-0000-000000000025', 'Progressive resistance exercise combined with adequate dietary protein intake has the strongest evidence base for improving muscle mass, strength and function in sarcopenia and frailty.', 2),
('d5000000-0000-0000-0000-000000000025', 'Frailty is a dynamic and potentially reversible or modifiable state, particularly when identified early, and should prompt active intervention rather than being viewed as an inevitable, fixed trajectory towards care dependency.', 3),
('d5000000-0000-0000-0000-000000000026', 'Fear of falling after a fall, even a minor one, can lead to activity avoidance, deconditioning and increased future falls risk, forming a self-perpetuating cycle that is a recognised post-fall syndrome.', 1),
('d5000000-0000-0000-0000-000000000026', 'Structured, individualised strength and balance training programmes (e.g. the Otago exercise programme) have strong evidence for reducing both falls incidence and fear of falling in community-dwelling older adults.', 2),
('d5000000-0000-0000-0000-000000000026', 'Sedative medications such as benzodiazepines should be avoided in the management of fear of falling, as they increase falls risk rather than mitigating it.', 3),
('d5000000-0000-0000-0000-000000000027', $x$Dopamine agonists (more so than levodopa) are a common cause of orthostatic hypotension in Parkinson's disease, and dose increases can precipitate or worsen postural falls.$x$, 1),
('d5000000-0000-0000-0000-000000000027', 'Management of drug-related orthostatic hypotension should start with reviewing and adjusting the causative medication and non-pharmacological measures, reserving pharmacological treatments (midodrine, fludrocortisone) for persistent symptomatic cases.', 2),
('d5000000-0000-0000-0000-000000000027', $x$Abrupt discontinuation of dopaminergic therapy in Parkinson's disease is dangerous and should be avoided; medication changes should be made gradually with specialist input where possible.$x$, 3),
('d5000000-0000-0000-0000-000000000028', 'Falls risk alone, in the absence of a prior intracranial haemorrhage or other major bleeding risk factors, is rarely sufficient justification to withhold anticoagulation in atrial fibrillation, since the stroke prevention benefit typically far outweighs the theoretical bleeding risk from falls.', 1),
('d5000000-0000-0000-0000-000000000028', 'Decisions about anticoagulation in frail or falls-prone older patients should be individualised, weighing stroke risk (e.g., CHA2DS2-VASc), bleeding risk (e.g., HAS-BLED, prior intracranial bleeding), and the underlying causes and modifiability of the falls, rather than applying a blanket rule based on falls frequency alone.', 2),
('d5000000-0000-0000-0000-000000000028', 'Continuing anticoagulation does not preclude, and should be accompanied by, active investigation and management of the underlying causes of recurrent falls.', 3),
('d5000000-0000-0000-0000-000000000029', 'Sulfonylureas such as gliclazide carry a significant risk of hypoglycaemia, which can present atypically in older people as falls, confusion or non-specific symptoms rather than classic adrenergic features alone.', 1),
('d5000000-0000-0000-0000-000000000029', 'Glycaemic targets should be individualised and relaxed in frail older patients with limited life expectancy or cognitive impairment, prioritising avoidance of hypoglycaemia over tight HbA1c control.', 2),
('d5000000-0000-0000-0000-000000000029', 'Recurrent unexplained falls in a patient with diabetes on a sulfonylurea or insulin should prompt specific enquiry about hypoglycaemic episodes and review of glucose-lowering therapy.', 3),
('d5000000-0000-0000-0000-000000000030', 'The Fried frailty phenotype is defined by meeting three or more of five criteria: unintentional weight loss, self-reported exhaustion, weakness (grip strength), slow gait speed, and low physical activity, and represents a distinct syndrome of reduced physiological reserve.', 1),
('d5000000-0000-0000-0000-000000000030', 'Frailty, comorbidity (multiple diagnoses) and disability (dependency in activities of daily living) are related but conceptually distinct constructs that frequently coexist but should be assessed and understood separately.', 2),
('d5000000-0000-0000-0000-000000000030', 'Comprehensive geriatric assessment, incorporating objective functional measures such as gait speed and grip strength, is required to accurately identify frailty, rather than relying on surrogate markers such as medication count, admission frequency, or age alone.', 3),
('d5000000-0000-0000-0000-000000000031', $x$After approximately 5 years of oral bisphosphonate therapy, fracture risk should be reassessed using DXA and clinical risk factors, with a treatment holiday considered in patients at lower ongoing risk, given the drug's prolonged skeletal retention.$x$, 1),
('d5000000-0000-0000-0000-000000000031', 'A bisphosphonate treatment holiday is a planned period of reassessment and monitoring, not permanent discontinuation, and treatment may need to resume if risk factors change or bone density declines.', 2),
('d5000000-0000-0000-0000-000000000031', 'Longer cumulative bisphosphonate exposure is associated with increased (though still rare) risks of atypical femoral fracture and osteonecrosis of the jaw, informing the rationale for periodic reassessment rather than indefinite treatment in lower-risk patients.', 3),
('d5000000-0000-0000-0000-000000000032', $x$Atypical femoral fractures are a rare complication of prolonged bisphosphonate (and to a lesser extent denosumab) therapy, characterised by prodromal thigh pain, a transverse or short oblique fracture with lateral cortical thickening ('beaking'), minimal trauma, and delayed healing.$x$, 1),
('d5000000-0000-0000-0000-000000000032', 'Management of a suspected atypical femoral fracture includes stopping the causative antiresorptive agent, ensuring adequate calcium and vitamin D, orthopaedic assessment, imaging of the contralateral femur (given bilateral risk), and consideration of anabolic therapy to promote healing.', 2),
('d5000000-0000-0000-0000-000000000032', 'Recognising the distinct clinical and radiological features of atypical femoral fracture, as opposed to a typical osteoporotic fragility fracture, is essential since the management (including antiresorptive cessation) differs substantially.', 3),
('d5000000-0000-0000-0000-000000000033', 'Medication-related osteonecrosis of the jaw is a rare complication of antiresorptive therapy, with substantially lower risk associated with oral bisphosphonates at osteoporosis doses compared with high-dose intravenous bisphosphonates or denosumab used in oncology settings.', 1),
('d5000000-0000-0000-0000-000000000033', 'Current guidance does not recommend interrupting oral bisphosphonate therapy for routine, low-risk dental procedures such as simple extractions in patients without additional risk factors (e.g., cancer treatment, radiotherapy, very long treatment duration).', 2),
('d5000000-0000-0000-0000-000000000033', 'Balancing the very low MRONJ risk against the substantial fracture risk reduction from continued osteoporosis treatment supports continuing bisphosphonates through routine dental care in most patients.', 3),
('d5000000-0000-0000-0000-000000000034', 'Patients at very high fracture risk (recent hip fracture, multiple vertebral fractures, markedly low bone density) benefit from an anabolic-first treatment strategy (teriparatide or romosozumab), which more effectively reduces fracture risk than starting with an antiresorptive agent alone.', 1),
('d5000000-0000-0000-0000-000000000034', 'Anabolic agents should be followed by an antiresorptive agent (bisphosphonate or denosumab) to consolidate and maintain the bone density gains achieved, as anabolic-induced gains can be lost if not followed by antiresorptive therapy.', 2),
('d5000000-0000-0000-0000-000000000034', 'A prior fragility fracture, particularly hip or multiple vertebral fractures, identifies patients at very high imminent risk of further fracture who warrant prompt and often more intensive treatment strategies.', 3),
('d5000000-0000-0000-0000-000000000035', 'Delayed, missed, or discontinued denosumab dosing is associated with a rebound increase in bone turnover and a risk of multiple vertebral fractures occurring within months, a phenomenon not seen with bisphosphonates due to their prolonged skeletal retention.', 1),
('d5000000-0000-0000-0000-000000000035', 'If denosumab is to be discontinued, transitioning to a bisphosphonate around the time of the next scheduled dose is recommended to mitigate rebound bone loss and vertebral fracture risk.', 2),
('d5000000-0000-0000-0000-000000000035', $x$Unlike bisphosphonates, denosumab's antiresorptive effect wanes relatively quickly after a missed or final dose, making timely follow-up dosing or bridging therapy particularly important with this agent.$x$, 3),
('d5000000-0000-0000-0000-000000000036', 'Both bisphosphonates and denosumab can cause hypocalcaemia, and this risk is significantly increased in patients with vitamin D deficiency and/or renal impairment, where calcium homeostasis is already compromised.', 1),
('d5000000-0000-0000-0000-000000000036', 'Vitamin D deficiency and inadequate calcium intake should be corrected before starting antiresorptive osteoporosis therapy to reduce the risk of treatment-induced hypocalcaemia.', 2),
('d5000000-0000-0000-0000-000000000036', 'Renal impairment influences the choice and monitoring of osteoporosis therapy (caution with bisphosphonates at low eGFR) but does not mean treatment should be withheld altogether once appropriate precautions are taken.', 3),
('d5000000-0000-0000-0000-000000000037', 'In patients anticipated to require long-term (over 3 months) moderate-to-high dose glucocorticoid therapy, bone protection decisions should use a risk assessment tool incorporating glucocorticoid dose (e.g., FRAX with glucocorticoid adjustment), and treatment should be started in high-risk patients without waiting for DXA.', 1),
('d5000000-0000-0000-0000-000000000037', 'Glucocorticoid-induced bone loss is most rapid in the early months of treatment, making prompt initiation of bone protection important rather than delaying pending imaging.', 2),
('d5000000-0000-0000-0000-000000000037', 'Calcium and vitamin D supplementation alone is inadequate bone protection for high-risk patients on long-term glucocorticoids; specific antiresorptive therapy is usually also required.', 3),
('d5000000-0000-0000-0000-000000000038', 'Oral bisphosphonates are contraindicated or should be used with caution in patients with significant oesophageal pathology (strictures, achalasia, severe reflux) due to risk of local irritation and ulceration.', 1),
('d5000000-0000-0000-0000-000000000038', 'Intravenous zoledronic acid (or subcutaneous denosumab) provides an effective alternative route of osteoporosis treatment for patients who cannot tolerate or safely take oral bisphosphonates.', 2),
('d5000000-0000-0000-0000-000000000038', 'Route of administration should be tailored to patient-specific contraindications and tolerability, rather than assuming all bisphosphonates within a class carry equivalent risk regardless of formulation.', 3),
('d5000000-0000-0000-0000-000000000039', 'Bisphosphonates are renally cleared and are generally avoided or used with significant caution at markedly reduced eGFR, due to concerns about drug accumulation and, particularly with intravenous agents, nephrotoxicity.', 1),
('d5000000-0000-0000-0000-000000000039', 'Denosumab is not renally cleared and can be used in advanced chronic kidney disease, but carries an increased risk of hypocalcaemia in this population, requiring calcium and vitamin D optimisation before treatment and close monitoring after each dose.', 2),
('d5000000-0000-0000-0000-000000000039', 'Selection of osteoporosis pharmacotherapy must account for renal function, since the safety profile of bisphosphonates and denosumab differs substantially in advanced chronic kidney disease.', 3),
('d5000000-0000-0000-0000-000000000040', 'Primary hyperparathyroidism is an important cause of secondary osteoporosis, and evidence of skeletal end-organ damage (fragility fracture, significantly reduced bone density) is a recognised indication for parathyroidectomy even in the absence of renal complications.', 1),
('d5000000-0000-0000-0000-000000000040', 'Parathyroidectomy is the definitive treatment for primary hyperparathyroidism in surgical candidates, addressing the underlying cause of bone loss rather than only its skeletal consequences.', 2),
('d5000000-0000-0000-0000-000000000040', 'Medical therapies such as bisphosphonates or cinacalcet are generally reserved for patients with primary hyperparathyroidism who are unsuitable for or decline surgery, rather than being used as an alternative to surgery in operable candidates with end-organ damage.', 3),
('d5000000-0000-0000-0000-000000000041', $x$The 'triple whammy' combination of an ACE inhibitor (or ARB), a diuretic, and an NSAID substantially increases the risk of acute kidney injury through combined effects on renal blood flow and glomerular filtration pressure.$x$, 1),
('d5000000-0000-0000-0000-000000000041', 'When acute kidney injury develops in a patient on this combination, the NSAID should typically be identified and stopped first, as it is often the most recently introduced, least essential, and most readily reversible contributing agent.', 2),
('d5000000-0000-0000-0000-000000000041', 'Older patients started on NSAIDs, even for common indications like osteoarthritis, should have their background medications reviewed for interacting nephrotoxic combinations before or shortly after initiation.', 3),
('d5000000-0000-0000-0000-000000000042', 'Cumulative anticholinergic burden from multiple drugs, even when each is individually low-risk, is associated with worsening cognition, confusion and falls in older people, and should be assessed using a structured tool rather than considering each drug in isolation.', 1),
('d5000000-0000-0000-0000-000000000042', 'Medication review to reduce anticholinergic burden should consider substitution with lower-burden alternatives (e.g., mirabegron instead of an antimuscarinic, non-anticholinergic analgesic strategies) rather than simply stopping treatment for the underlying condition without an alternative.', 2),
('d5000000-0000-0000-0000-000000000042', 'A valid original indication for a medication does not guarantee ongoing appropriateness; periodic review is essential, especially when there is evidence of cumulative harm.', 3),
('d5000000-0000-0000-0000-000000000043', 'Long-term benzodiazepine use should be discontinued through a gradual, individualised dose reduction rather than abrupt cessation, given the risk of a withdrawal syndrome including, in severe cases, seizures.', 1),
('d5000000-0000-0000-0000-000000000043', 'Deprescribing benzodiazepines in older people should be accompanied by monitoring for withdrawal symptoms and, where relevant, support for the underlying condition (such as anxiety) that the medication was originally treating.', 2),
('d5000000-0000-0000-0000-000000000043', 'The pace of a benzodiazepine taper should be individualised, and may need to be slower after very long-term use, rather than following a fixed universal schedule.', 3),
('d5000000-0000-0000-0000-000000000044', 'Statins have a long time-to-benefit for cardiovascular risk reduction, meaning their continuation should be reconsidered in patients with a limited life expectancy where this benefit is unlikely to be realised.', 1),
('d5000000-0000-0000-0000-000000000044', $x$Deprescribing decisions in advanced frailty and terminal illness should be guided by the patient's overall goals of care and prognosis, shifting the balance towards reducing medication burden and focusing on comfort rather than long-term preventive benefit.$x$, 2),
('d5000000-0000-0000-0000-000000000044', 'A shared decision-making conversation with the patient (where possible) and family is an important part of deprescribing preventive medications in the context of limited prognosis, rather than making unilateral or purely protocol-driven changes.', 3),
('d5000000-0000-0000-0000-000000000045', 'Clarithromycin (and other macrolides such as erythromycin) are well-recognised inhibitors of warfarin metabolism, and can precipitate a significant, sometimes dangerous, rise in INR when co-prescribed.', 1),
('d5000000-0000-0000-0000-000000000045', $x$New prescriptions of medications with known CYP450-interacting properties should be checked against a patient's existing anticoagulant therapy, ideally choosing a non-interacting alternative where clinically appropriate.$x$, 2),
('d5000000-0000-0000-0000-000000000045', 'Management of a markedly supratherapeutic INR with bleeding involves addressing the underlying cause (stopping the interacting drug), withholding the anticoagulant, and using appropriate reversal measures guided by the severity of bleeding and INR level.', 3),
('d5000000-0000-0000-0000-000000000046', 'Long-term proton pump inhibitor use without an ongoing clear indication is associated with recognised risks including increased fracture risk, Clostridioides difficile infection, hypomagnesaemia, and vitamin B12 deficiency, particularly relevant in older people.', 1),
('d5000000-0000-0000-0000-000000000046', 'Deprescribing long-term PPIs should generally involve a gradual dose reduction (rather than abrupt cessation) to reduce the risk of rebound acid hypersecretion and transient symptom recurrence, with a plan to reintroduce treatment if symptoms genuinely recur.', 2),
('d5000000-0000-0000-0000-000000000046', $x$Ongoing PPI use should be regularly reviewed against clear indications (e.g., Barrett's oesophagus, continued NSAID use, severe erosive disease) rather than continued indefinitely once the original indication has resolved.$x$, 3),
('d5000000-0000-0000-0000-000000000047', 'Co-prescribing opioids and benzodiazepines has an additive, sometimes synergistic, sedative and respiratory depressant effect, substantially increasing the risk of over-sedation, respiratory depression, and falls, particularly in older people.', 1),
('d5000000-0000-0000-0000-000000000047', 'Acute management of significant sedation/respiratory depression from this combination involves withholding further doses and close monitoring (with naloxone available for severe cases), while longer-term management involves a planned, supervised taper rather than abrupt discontinuation of chronic opioid therapy.', 2),
('d5000000-0000-0000-0000-000000000047', 'New or recently added sedating medications (such as a benzodiazepine started during an unrelated admission) should be scrutinised first when a patient on established chronic therapy develops new toxicity, rather than assuming the long-standing medication is solely responsible.', 3),
('d5000000-0000-0000-0000-000000000048', $x$Diuretic-induced hypokalaemia is a common and important precipitant of digoxin toxicity, as reduced potassium increases digoxin's binding to the Na+/K+-ATPase pump and heightens myocardial sensitivity to its arrhythmogenic effects.$x$, 1),
('d5000000-0000-0000-0000-000000000048', 'Management of digoxin toxicity centres on withholding the drug and correcting precipitating electrolyte disturbances, with digoxin-specific antibody fragments reserved for severe or life-threatening presentations rather than used routinely.', 2),
('d5000000-0000-0000-0000-000000000048', 'New diuretic prescriptions in patients on digoxin should prompt closer monitoring of renal function and electrolytes, given the well-recognised interaction risk between diuretic-induced hypokalaemia and digoxin toxicity.', 3),
('d5000000-0000-0000-0000-000000000049', 'First-generation antihistamines such as chlorphenamine and promethazine have substantial anticholinergic and sedative effects and are explicitly identified by prescribing criteria (STOPP, Beers) as generally inappropriate for regular use in older people.', 1),
('d5000000-0000-0000-0000-000000000049', 'New confusion, drowsiness, or falls in a patient taking a sedating anticholinergic medication should prompt discontinuation of that drug rather than dose escalation or substitution with a similarly problematic alternative.', 2),
('d5000000-0000-0000-0000-000000000049', 'Where ongoing symptom control is needed, lower-burden alternatives (non-sedating second-generation antihistamines, non-pharmacological sleep measures) should be considered in place of long-term first-generation antihistamine use in older people.', 3),
('d5000000-0000-0000-0000-000000000050', $x$A prescribing cascade occurs when a new drug is started to treat a side effect of an existing medication that is not recognised as a drug-induced problem, potentially compounding the patient's medication burden and risk of further adverse effects.$x$, 1),
('d5000000-0000-0000-0000-000000000050', 'Dihydropyridine calcium channel blockers such as amlodipine cause ankle oedema through vasodilation rather than fluid overload, meaning diuretics are generally ineffective for this specific type of oedema and should not be used to treat it.', 2),
('d5000000-0000-0000-0000-000000000050', 'Recognising and unwinding a prescribing cascade requires identifying and addressing the original causative drug, rather than continuing to add or escalate treatments aimed at managing the resulting adverse effect.', 3);
